        for x: CGFloat in [-37, 39] { for y: CGFloat in [-80, -17] { rivet(.init(x: x, y: y), radius: 2.3) } }
        oval(CGRect(x: -11, y: -134, width: 22, height: 24), [0xFFF0BB, 0xB79454])
