            for y: CGFloat in [-77, -6] { p.rounded(CGRect(x: -30, y: y, width: 60, height: 8), 3, [0xFFE5AA, 0xCCA56E, 0xA28C62]) }
            p.line([.init(x: -12, y: -63), .init(x: -11, y: -53), .init(x: -6, y: -44)], 0xFFFFFF, 1.7, opacity: 0.85)
        }
