    private func chartTable(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.groundShadow(width: 80, height: 14)
            for x: CGFloat in [-26, 24] {
                p.rounded(CGRect(x: x - 3, y: -25, width: 6, height: 36), 2, [0xC49A63, 0x705139])
                p.line([.init(x: x - 1, y: -21), .init(x: x - 1, y: 7)], 0xE3BF85, 0.8)
            }
            p.rounded(CGRect(x: -35, y: -29, width: 70, height: 8), 3, [0xE4BF81, 0x9F7546])
            for x: CGFloat in [-21, 0, 20] { p.line([.init(x: x, y: -28), .init(x: x + 1, y: -22)], 0x7C5D3B, 0.7) }
            // Rolled parchment, a red route, a compass and loose coins.
            p.polygon([.init(x: -25, y: -34), .init(x: 10, y: -37), .init(x: 16, y: -24), .init(x: -24, y: -23)], [0xFFF2CF, 0xD7B77E])
            p.oval(CGRect(x: -28, y: -35, width: 6, height: 14), [0xFFF7DE, 0xD1AE73])
            p.line([.init(x: -19, y: -29), .init(x: -12, y: -32), .init(x: -6, y: -27), .init(x: 2, y: -31)], 0xB87858, 1)
            for side: CGFloat in [-1, 1] { p.line([.init(x: 5, y: -33 + side * 2), .init(x: 10, y: -33 - side * 2)], 0xBC6950, 1) }
            p.oval(CGRect(x: 17, y: -35, width: 11, height: 8), [0xFFECB0, 0xB9964E])
            p.oval(CGRect(x: 19, y: -34, width: 7, height: 5), [0xE5EFE1, 0x9CB6AC])
            p.line([.init(x: 21, y: -30), .init(x: 24, y: -33)], 0x8E6251, 0.8)
            p.coin(at: .init(x: 30, y: -25), size: 0.67)
        }
    }

    private func camp(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.groundShadow(width: 108, height: 18)
            // Four planted posts carry the rear rail and the lower front beam.
            p.post(at: .init(x: -42, y: -1), height: 90)
            p.post(at: .init(x: 40, y: -2), height: 99)
            for (a, b): (CGPoint, CGPoint) in [
                (.init(x: -42, y: -86), .init(x: 40, y: -96)),
                (.init(x: -42, y: -86), .init(x: -43, y: -46)),
                (.init(x: 40, y: -96), .init(x: 48, y: -56))
            ] { p.line([a, b], 0x967047, 4.2) }
            p.line([.init(x: -42, y: -22), .init(x: -27, y: -47)], 0xB88C57, 3)
            p.line([.init(x: 48, y: -28), .init(x: 33, y: -54)], 0xB88C57, 3)
            p.post(at: .init(x: -43, y: 11), height: 62)
            p.post(at: .init(x: 48, y: 1), height: 62)
            p.line([.init(x: -43, y: -41), .init(x: 48, y: -51)], 0x9A7147, 5)
            var tent = Path(); tent.move(to: .init(x: -42, y: -86)); tent.addLine(to: .init(x: 40, y: -96))
            tent.addQuadCurve(to: .init(x: 48, y: -56), control: .init(x: 39, y: -74))
            tent.addLine(to: .init(x: -43, y: -46))
            tent.addQuadCurve(to: .init(x: -42, y: -86), control: .init(x: -39, y: -65)); tent.closeSubpath()
            p.material(tent, [0xFFF7D9, 0xF1D9A6, 0xD7BD8D])
            p.context.drawLayer { c in
                c.clip(to: tent)
                for i in 0..<7 where i % 2 == 0 {
                    let a = CGFloat(i) / 7, b = CGFloat(i + 1) / 7
                    var stripe = Path(); stripe.addLines([
                        .init(x: -42 + 82 * a, y: -86 - 10 * a), .init(x: -42 + 82 * b, y: -86 - 10 * b),
                        .init(x: -43 + 91 * b, y: -46 - 10 * b), .init(x: -43 + 91 * a, y: -46 - 10 * a)
                    ]); stripe.closeSubpath()
                    c.fill(stripe, with: .linearGradient(Gradient(colors: [Color(dinoHex: 0xDC866C), Color(dinoHex: 0xB76754)]), startPoint: .init(x: 0, y: -96), endPoint: .init(x: 0, y: -46)))
                }
            }
            for i in 1..<7 {
                let t = CGFloat(i) / 7
                p.line([.init(x: -42 + 82 * t, y: -86 - 10 * t), .init(x: -43 + 91 * t, y: -46 - 10 * t)], 0xFFF0C8, 0.65, opacity: 0.58)
            }
            for i in 0..<7 {
                let x = -43 + CGFloat(i) * 13, y = -46 - CGFloat(i) * 10 / 7
                var hem = Path(); hem.move(to: .init(x: x, y: y))
                hem.addLine(to: .init(x: x + 13, y: y - 10 / 7))
                hem.addLine(to: .init(x: x + 13, y: y + 5))
                hem.addCurve(to: .init(x: x, y: y + 7), control1: .init(x: x + 12, y: y + 14), control2: .init(x: x + 1, y: y + 15))
                hem.closeSubpath()
                p.material(hem, i % 2 == 0 ? [0xDC8A70, 0xAD6151] : [0xFFF0CE, 0xD5BA88])
                p.line([.init(x: x + 1, y: y + 1), .init(x: x + 12, y: y - 0.6)], 0xFFE7BE, 0.65, opacity: 0.7)
            }
            p.line([.init(x: -42, y: -86), .init(x: 40, y: -96)], 0xEBD8AC, 1.7)
            for corner: CGPoint in [.init(x: -42, y: -86), .init(x: 40, y: -96), .init(x: -43, y: -46), .init(x: 48, y: -56)] {
                p.oval(CGRect(x: corner.x - 1.7, y: corner.y - 1.3, width: 3.4, height: 2.6), [0xA5804D, 0x795E3C])
                for dy: CGFloat in [2, 4] {
                    p.line([.init(x: corner.x - 4, y: corner.y + dy), .init(x: corner.x + 4, y: corner.y + dy - 1)], 0xF1D6A0, 1.2)
                }
            }
            p.barrel(at: CGPoint(x: 43, y: 8), size: 0.75)
            p.line([.init(x: -43, y: -34), .init(x: -50, y: -34), .init(x: -50, y: -28)], 0x776A4D, 1.4)
            p.lantern(at: CGPoint(x: -50, y: -3), size: 0.62)
            p.chartTable(at: CGPoint(x: -1, y: 12), size: 1)
            p.chest(at: .init(x: -21, y: 30), size: 0.51)
        }
    }
    func scene(at point: CGPoint, size: CGFloat, variation: Int) {
        // Previews can show a vessel too; the map places ships directly in the water.
        if variation % 4 == 1 { ship(at: point, size: size * 0.94); return }
        at(point, size: size, radius: 74 * size, rise: 135 * size) { p in
            if variation == 8 {
                p.hourglass(at: CGPoint(x: -1, y: 12), size: 1.22)
                p.chest(at: CGPoint(x: -43, y: 20), size: 0.55)
                p.lantern(at: CGPoint(x: 46, y: 8), size: 0.77)
            } else {
                switch variation % 4 {
                case 0:
                    p.palm(at: CGPoint(x: 26, y: -8), size: 0.94)
                    p.camp(at: CGPoint(x: -8, y: 1), size: 0.96)
                case 2:
                    p.palm(at: CGPoint(x: -27, y: -3), size: 0.83)
                    if variation == 2 { p.hourglass(at: CGPoint(x: 27, y: 1), size: 0.76) }
                    p.chest(at: CGPoint(x: -8, y: 12), size: 1.02)
                    if variation != 2 {
                        p.barrel(at: .init(x: 39, y: 13), size: 0.79)
                        p.conch(at: .init(x: 39, y: -13), size: 0.48)
                        p.lantern(at: .init(x: 56, y: 17), size: 0.46)
                    }
                default:
                    p.rock(at: CGPoint(x: 15, y: 3), size: 1.19)
                    p.barrel(at: CGPoint(x: -27, y: 13), size: 0.91)
                    p.barrel(at: CGPoint(x: -3, y: 17), size: 0.72)
                    p.anchor(at: CGPoint(x: 24, y: 11), size: 1.08)
                    p.lantern(at: CGPoint(x: -27, y: -15), size: 0.72)
                }
            }
            p.plants(at: CGPoint(x: -47, y: 38), size: 0.68, flowers: true)
            p.shell(at: CGPoint(x: 45, y: 30), size: 0.59)
            p.starfish(at: CGPoint(x: -22, y: 30), size: 0.67)
        }
    }
    /// Feathered leaflets follow a curved rachis, giving each frond an open silhouette.
    private func frond(from root: CGPoint, to tip: CGPoint, arch: CGFloat, width: CGFloat, light: Bool) {
        let control = CGPoint(x: (root.x + tip.x) * 0.5, y: min(root.y, tip.y) - arch)
        func point(_ t: CGFloat) -> CGPoint {
            let u = 1 - t
            return CGPoint(x: u * u * root.x + 2 * u * t * control.x + t * t * tip.x,
                           y: u * u * root.y + 2 * u * t * control.y + t * t * tip.y)
        }
        for i in 1...12 {
            let t = CGFloat(i) / 14, a = point(t), b = point(min(1, t + 0.14))
            let dx = b.x - a.x, dy = b.y - a.y, length = max(0.1, hypot(dx, dy))
            let spread = width * pow(sin(t * .pi), 0.65)
            for side: CGFloat in [-1, 1] {
                let end = CGPoint(x: b.x - dy / length * spread * side, y: b.y + dx / length * spread * side + 3)
                var leaflet = Path(); leaflet.move(to: a)
                leaflet.addQuadCurve(to: end, control: CGPoint(x: a.x - dy / length * spread * side * 0.9, y: a.y + dx / length * spread * side * 0.9))
                leaflet.addQuadCurve(to: CGPoint(x: a.x + dx * 0.5, y: a.y + dy * 0.5), control: CGPoint(x: b.x, y: b.y + 3))
                leaflet.closeSubpath()
                material(leaflet, light ? [0xC5DA68, 0x78AD49, 0x32764F] : [0x8EBE58, 0x41894F, 0x245E4D])
                if i % 3 == 0 { line([a, end], 0xD6DC89, 0.45, opacity: 0.42) }
            }
        }
        var rib = Path(); rib.move(to: root); rib.addQuadCurve(to: tip, control: control)
        context.stroke(rib, with: .color(Color(dinoHex: light ? 0xD6D78B : 0x91AC63)), style: StrokeStyle(lineWidth: 1.2, lineCap: .round))
    }

    private func groundShadow(width: CGFloat, height: CGFloat = 16) {
        var c = context; c.scaleBy(x: 1, y: height / width)
        c.fill(Path(ellipseIn: CGRect(x: -width / 2, y: -width / 2, width: width, height: width)),
               with: .radialGradient(Gradient(colors: [Color(dinoHex: 0x6B7658).opacity(0.24), .clear]), center: .zero, startRadius: 0, endRadius: width / 2))
    }

    /// Independent, stable samples avoid diagonal bands from paired remainders.
    private func scatter(_ seed: Int) -> CGFloat {
        var value = UInt32(truncatingIfNeeded: seed) &+ 0x9E3779B9
        value = (value ^ (value >> 16)) &* 0x7FEB352D
        value = (value ^ (value >> 15)) &* 0x846CA68B
        value ^= value >> 16
        return CGFloat(value & 0x00FFFFFF) / 16_777_215
    }

    private func coin(at point: CGPoint, size: CGFloat = 1, angle: Double = 0) {
        at(point, size: size) { base in
            var c = base.context; c.rotate(by: .degrees(angle))
            let p = PirateCoastPainter(context: c)
            p.oval(CGRect(x: -4.4, y: -1, width: 8.8, height: 4), [0xE5AD38, 0xA46A23])
            p.oval(CGRect(x: -4.4, y: -2.3, width: 8.8, height: 3.9), [0xFFF3AD, 0xF6D05A, 0xD9972E])
            p.context.stroke(Path(ellipseIn: CGRect(x: -2.8, y: -1.7, width: 5.6, height: 2.3)), with: .color(Color(dinoHex: 0xB88432).opacity(0.7)), lineWidth: 0.5)
            p.line([.init(x: -1, y: -1), .init(x: 1.4, y: -0.8)], 0xFFF8CA, 0.6)
        }
    }

    private func treasure(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.groundShadow(width: 93, height: 17)
            var loose: [(point: CGPoint, size: CGFloat, angle: Double)] = []
            for i in 0..<53 {
                let direction = p.scatter(i * 7 + 17) * .pi * 2
                let distance = sqrt(p.scatter(i * 7 + 53))
                let point = CGPoint(x: cos(direction) * distance * 43,
                                    y: sin(direction) * distance * 12 + 2)
                loose.append((point, 0.58 + p.scatter(i * 7 + 83) * 0.43,
                              Double(p.scatter(i * 7 + 107) * 54 - 27)))
            }
            for coin in loose.sorted(by: { $0.point.y < $1.point.y }) {
                p.coin(at: coin.point, size: coin.size, angle: coin.angle)
            }
            for (index, stack) in [(x: CGFloat(-23), y: CGFloat(7), count: 3),
                                   (x: 13, y: 10, count: 3), (x: 31, y: 2, count: 2)].enumerated() {
                for j in 0..<stack.count {
                    let seed = index * 19 + j * 3
                    p.coin(at: .init(x: stack.x + p.scatter(seed + 601) * 1.8 - 0.9,
                                     y: stack.y - CGFloat(j) * 2 + p.scatter(seed + 613) * 0.8),
                           size: 0.84 + p.scatter(seed + 631) * 0.13,
                           angle: Double(p.scatter(seed + 643) * 20 - 10))
                }
            }
            for (x,y): (CGFloat,CGFloat) in [(-15,9),(24,14),(-37,3)] {
                p.polygon([.init(x:x-3,y:y),.init(x:x-1,y:y-4),.init(x:x+3,y:y-3),.init(x:x+4,y:y),.init(x:x,y:y+4)], [0xB8F4E4,0x43AFAD,0x307A91])
                p.line([.init(x:x-1,y:y-3),.init(x:x+1,y:y)],0xF1FFEF,0.65)
            }
            for i in 0..<13 {
                let t = CGFloat(i) / 12, x = -8 + t * 29, y = 15 + sin(t * .pi) * 5
                p.oval(CGRect(x:x-1.5,y:y-1.5,width:3,height:3),[0xFFFCED,0xE2D9C0,0xB5B8AC])
            }
            for (x,y): (CGFloat,CGFloat) in [(-23,-5),(20,-2),(34,8)] {
                p.line([.init(x:x-2,y:y),.init(x:x+2,y:y)],0xFFF8CD,0.8)
                p.line([.init(x:x,y:y-3),.init(x:x,y:y+3)],0xFFF8CD,0.8)
            }
        }
    }

    /// Friendly, hand-drawn Jolly Roger: the same insignia on sail and flag.
    private func pirateMark(at point: CGPoint, size: CGFloat, ink: UInt32) {
        at(point, size: size) { p in
            let cutout: UInt32 = ink == 0x625A49 ? 0xEFD9AF : 0x314548
            for side: CGFloat in [-1, 1] {
                p.line([.init(x:-13,y:9 * side + 12),.init(x:13,y:-9 * side + 12)],ink,3)
                for (x,y): (CGFloat,CGFloat) in [(-13,9*side+12),(13,-9*side+12)] {
                    p.oval(CGRect(x:x-2.4,y:y-2.6,width:4.8,height:5.2),[ink,ink])
                }
            }
            p.oval(CGRect(x:-12,y:-18,width:24,height:24),[ink,ink])
            p.rounded(CGRect(x:-7,y:0,width:14,height:10),2,[ink,ink])
            for x: CGFloat in [-5,5] { p.oval(CGRect(x:x-3,y:-10,width:6,height:7),[cutout,cutout]) }
            p.polygon([.init(x:0,y:-4),.init(x:-2,y:0),.init(x:2,y:0)],[cutout,cutout])
            for x: CGFloat in [-3,0,3] { p.line([.init(x:x,y:5),.init(x:x,y:9)],cutout,0.7) }
        }
    }

    private func conch(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.groundShadow(width: 25,height: 6)
            var body = Path(); body.move(to:.init(x:-13,y:3))
            body.addCurve(to:.init(x:10,y:-5),control1:.init(x:-12,y:-14),control2:.init(x:7,y:-17))
            body.addLine(to:.init(x:19,y:3)); body.addQuadCurve(to:.init(x:-13,y:3),control:.init(x:0,y:11)); body.closeSubpath()
            p.material(body,[0xFFF3D5,0xE8B9A5,0xC08F87])
            var spiral=Path(); spiral.move(to:.init(x:9,y:1))
            spiral.addCurve(to:.init(x:-5,y:-6),control1:.init(x:6,y:-12),control2:.init(x:-9,y:-12))
            spiral.addCurve(to:.init(x:2,y:-2),control1:.init(x:-7,y:1),control2:.init(x:3,y:3))
            p.context.stroke(spiral,with:.color(Color(dinoHex:0xBD8E83)),style:StrokeStyle(lineWidth:1.2,lineCap:.round))
            for i in 0..<4 { p.line([.init(x:CGFloat(i)*4-5,y:4),.init(x:CGFloat(i)*4-3,y:1)],0xFFF8DF,0.9) }
        }
    }

    /// Details use the very same inlet mask as the shoreline, including its side exits.
    private func waterDetails(layout: WorldSceneryLayout) {
        for right in [false,true] {
            let water = layout.pirateWaterArea(right:right)
            var clipped=context;clipped.clip(to:water)
            let p=PirateCoastPainter(context:clipped)
            let scale=layout.scale
            // Sandbars below the surface and fine broken caustics add depth.
            let rows=Int(ceil(layout.height / (66*scale)))
            let columns=Int(ceil(layout.width / (57*scale)))
            for row in 0...rows {
                for column in 0...columns {
                    let seed = (row * 193 + column * 317 + row * column * 71) % 997
                    let x = (CGFloat(column) * 57 + CGFloat(seed % 47) - 23) * scale
                    let y = CGFloat(row) * 66 * scale - layout.routeOffset + CGFloat(seed % 53 - 26) * scale
                    let point=CGPoint(x:x,y:y)
                    guard water.contains(point) else { continue }
                    if seed % 4 == 0 {
                        var haze = clipped; haze.opacity = 0.17
                        haze.fill(Path(ellipseIn: CGRect(x: x - 32 * scale, y: y - 12 * scale, width: 64 * scale, height: 24 * scale)),
                                  with: .radialGradient(Gradient(colors: [Color(dinoHex: 0xD7F1CA), .clear]), center: point, startRadius: 0, endRadius: 35 * scale))
                    }
                    if seed%3 == 0 {
                        var underwater=clipped;underwater.opacity=0.40
                        PirateCoastPainter(context:underwater).rock(at:point,size:scale*(0.18+CGFloat(seed%4)*0.05),wet:true)
                    }
                    if seed%13 == 0 { p.coral(at:.init(x:x+12*scale,y:y+6*scale),size:scale*0.30) }
                }
            }
        }
    }

    private func shoreRocks(layout: WorldSceneryLayout, depth: WorldSceneryDepth, depthOffset: CGFloat) {
        let painter = PirateCoastPainter(context: context, depth: depth, depthOffset: depthOffset)
        for rock in PirateCoastLayout.landRocks(layout: layout) {
            painter.rock(at: rock.point, size: rock.size)
        }
    }

    private func beachDetails(layout: WorldSceneryLayout) {
        let waters=[false,true].map { layout.pirateWaterArea(right:$0) }
        for i in 0..<72 {
            let right=i%2 == 0, sign:CGFloat=right ? 1:-1
            let y=CGFloat(15+(i*73)%1580)
            let distance=CGFloat(61+(i*17)%47)*layout.scale
            let point=CGPoint(x:layout.centerX(at:y)+sign*distance,y:y)
            let radius:CGFloat=(i%4 == 0 ? 12:7)*layout.scale
            guard point.x > radius && point.x < layout.width - radius,
                  [-radius, 0, radius].allSatisfy({ dy in
                      abs(point.x - layout.centerX(at: y + dy)) >= 46 + radius
                  }),
                  !waters.contains(where: { water in
                      [-radius, 0, radius].contains { dy in
                          [-radius, 0, radius].contains { dx in
                              water.contains(CGPoint(x: point.x + dx, y: y + dy))
                          }
                      }
                  }) else { continue }
            at(point,size:layout.scale*(0.33+CGFloat(i%3)*0.10)) { p in
                // Rotation and three shell shapes avoid a repeated border motif.
                var c=p.context;c.rotate(by:.degrees(Double((i*47)%100-50)))
                let detail=PirateCoastPainter(context:c)
                switch i%5 {
                case 0: detail.starfish(at:.zero,size:1.06)
                case 1: detail.conch(at:.zero,size:0.89)
                case 2: detail.shell(at:.zero,size:0.78)
                default:
                    for j in 0..<3 { detail.oval(CGRect(x:CGFloat(j)*5-6,y:CGFloat(j%2)*3,width:5,height:3),[0xF3E8C8,0xC5B190]) }
                }
                for j in 0..<4 { p.oval(CGRect(x:CGFloat(j)*7-11,y:9+CGFloat(j%2)*3,width:1.6,height:1),[0xA9936B,0xDAC495]) }
            }
        }
    }

}


/// Prepared shores are shared by waves, boats and birds. Timelines only sample them.
private struct PirateSeaGeometry {
    struct Coast {
        let points: [CGPoint]
        let water: Path
        let right: Bool

        func edgeX(at y: CGFloat) -> CGFloat {
            guard let first = points.first, let last = points.last else { return 0 }
            if y <= first.y { return first.x }
            if y >= last.y { return last.x }
            let step = (last.y - first.y) / CGFloat(points.count - 1)
            let index = min(points.count - 2, max(0, Int((y - first.y) / step)))
            let a = points[index], b = points[index + 1]
            let t = (y - a.y) / (b.y - a.y)
            return a.x + (b.x - a.x) * t
        }
    }
    let layout: WorldSceneryLayout
    let coasts: [Coast]
    let vessels: [PirateCoastLayout.Vessel]

    init(layout: WorldSceneryLayout) {
        self.layout = layout
        coasts = [false, true].map { right in
            let points = PirateCoastLayout.shoreline(layout: layout, right: right)
            var water = Path(); water.addLines(points)
            let outside: CGFloat = right ? layout.width + 400 : -400
            water.addLine(to: .init(x: outside, y: points.last!.y))
            water.addLine(to: .init(x: outside, y: points.first!.y)); water.closeSubpath()
            return Coast(points: points, water: water, right: right)
        }
        vessels = PirateCoastLayout.vessels(layout: layout)
    }
}

private enum PirateSeaMotion {
    static let speed: CGFloat = 6
    static let spacing: CGFloat = 52

    struct BoatPose {
        let point: CGPoint
        let angle: Double
    }
    static func boat(_ vessel: PirateCoastLayout.Vessel, sea: PirateSeaGeometry, time: Double) -> BoatPose {
        let distance = abs(vessel.point.x - sea.coasts[0].edgeX(at: vessel.point.y)) / sea.layout.scale
        let phase = (time * Double(speed) + Double(distance)) * .pi * 2 / Double(spacing)
        return BoatPose(point: .init(x: vessel.point.x + CGFloat(sin(phase)) * 0.55 * sea.layout.scale,
                                    y: vessel.point.y - CGFloat(cos(phase)) * 1.5 * sea.layout.scale),
                        angle: (sin(phase) * 1.1 + sin(phase * 2) * 0.20) * .pi / 180)
    }
}

private struct PirateCoastLife: View {
    let routeOffset: CGFloat
    let viewportHeight: CGFloat
    var fixedTime: TimeInterval? = nil
    var frozen = false

    var body: some View {
        GeometryReader { geometry in
            let layout = WorldSceneryLayout(width: geometry.size.width, height: geometry.size.height, routeOffset: routeOffset)
            let sea = PirateSeaGeometry(layout: layout)
            ZStack(alignment: .topLeading) {
                ForEach(0..<Int(ceil(geometry.size.height / 320)), id: \.self) { index in
                    let frame = CGRect(x: 0, y: CGFloat(index) * 320, width: geometry.size.width,
                                       height: min(320, geometry.size.height - CGFloat(index) * 320))
                    PirateCoastLifeSurface(sea: sea, frame: frame, viewportHeight: viewportHeight,
                                           fixedTime: fixedTime, frozen: frozen)
                        .mask(PirateCoastOcclusion(layout: layout, frame: frame, cutoff: -.infinity))
                        .modifier(MapAnimationVisibility(viewportHeight: viewportHeight, alwaysVisible: fixedTime != nil || frozen))
                        .frame(width: frame.width, height: frame.height).position(x: frame.midX, y: frame.midY)
                }
                ForEach(Array(sea.vessels.enumerated()), id: \.offset) { item in
                    let boat = item.element
                    let frame = CGRect(x: boat.point.x - 85 * boat.size, y: routeOffset + boat.point.y - 158 * boat.size,
                                       width: 170 * boat.size, height: 207 * boat.size)
                    PirateCoastLifeSurface(sea: sea, frame: frame, viewportHeight: viewportHeight, vessel: boat,
                                           fixedTime: fixedTime, frozen: frozen)
                        .mask(PirateCoastOcclusion(layout: layout, frame: frame, cutoff: routeOffset + boat.point.y))
                        .modifier(MapAnimationVisibility(viewportHeight: viewportHeight, alwaysVisible: fixedTime != nil || frozen))
                        .frame(width: frame.width, height: frame.height).position(x: frame.midX, y: frame.midY)
                }
            }
        }.clipped().allowsHitTesting(false).accessibilityHidden(true)
    }
}

private struct PirateCoastOcclusion: View {
    let layout: WorldSceneryLayout
    let frame: CGRect
    let cutoff: CGFloat

    var body: some View {
        Canvas { context, size in
            context.fill(Path(CGRect(origin: .zero, size: size)), with: .color(.white))
            var c = context; c.translateBy(x: -frame.minX, y: -frame.minY)
            c.blendMode = .destinationOut
            let depth = WorldSceneryDepth(minimumDepth: cutoff, visibleBounds: frame)
            PirateCoastPainter(context: c, animatedVessels: true).appendScenery(layout: layout, depth: depth)
            depth.draw()
            let point = CGPoint(x: layout.width - 79 * layout.scale, y: layout.routeOffset + 1675)
            if point.y > cutoff && frame.intersects(CGRect(x: point.x - 95 * layout.scale, y: point.y - 180 * layout.scale,
                                                         width: 190 * layout.scale, height: 225 * layout.scale)) {
                WorldBossPainter(context: c).draw(worldID: 9, at: point, size: layout.scale * 0.88)
                c.fill(Path(roundedRect: CGRect(x: point.x - 70 * layout.scale, y: point.y - 4 * layout.scale,
                                               width: 140 * layout.scale, height: 40 * layout.scale), cornerRadius: 6 * layout.scale),
                       with: .color(.white))
            }
        }
    }
}

private struct PirateCoastLifeSurface: View {
    let sea: PirateSeaGeometry
    let frame: CGRect
    let viewportHeight: CGFloat
    var vessel: PirateCoastLayout.Vessel? = nil
    var fixedTime: TimeInterval? = nil
    var frozen = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.dinoMapAnimationEpoch) private var animationEpoch
    @State private var visible = false

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 20,
                                paused: fixedTime != nil || frozen || reduceMotion || !visible || scenePhase != .active)) { timeline in
            Canvas { context, _ in
                let time = frozen || reduceMotion ? 0 : (fixedTime ?? timeline.date.timeIntervalSince(animationEpoch ?? Date(timeIntervalSinceReferenceDate: 0)))
                var c = context; c.translateBy(x: -frame.minX, y: sea.layout.routeOffset - frame.minY)
                if let vessel {
                    let pose = PirateSeaMotion.boat(vessel, sea: sea, time: time)
                    c.translateBy(x: pose.point.x, y: pose.point.y); c.rotate(by: .radians(pose.angle))
                    PirateCoastPainter(context: c).ship(at: .zero, size: vessel.size)
                } else {
                    PirateSeaPainter(context: c).waves(sea: sea, frame: frame, time: time)
                }
            }
        }
        .readGeometry(for: Bool.self) { proxy in
            let rect = proxy.frame(in: .named("adventure.map.viewport"))
            return rect.maxY > -256 && rect.minY < viewportHeight + 256
        } action: { visible = $0 }
    }
}

private struct PirateSeaPainter {
    let context: GraphicsContext

    func waves(sea: PirateSeaGeometry, frame: CGRect, time: Double) {
        let scale = sea.layout.scale, spacing = PirateSeaMotion.spacing * scale
        let travel = CGFloat(time) * PirateSeaMotion.speed * scale
        let first = Int(floor(travel / spacing))
        let start = Int(floor((frame.minY - sea.layout.routeOffset - 50 * scale) / (54 * scale)))
        let end = Int(ceil((frame.maxY - sea.layout.routeOffset + 50 * scale) / (54 * scale)))
        for coast in sea.coasts {
            var c = context; c.clip(to: coast.water)
            let sign: CGFloat = coast.right ? 1 : -1
            for band in 0...Int(ceil(sea.layout.width / spacing)) {
                let waveID = first + band
                let distance = CGFloat(waveID + 1) * spacing - travel
                let fade = min(1, max(0, distance / (20 * scale)))
                for row in start...end {
                    let seed = abs(row * 37 + waveID * 19 + (coast.right ? 11 : 0)) % 97
                    let y = CGFloat(row) * 54 * scale + CGFloat(seed % 23 - 11) * scale
                    let length = CGFloat(22 + seed % 17) * scale
                    var crest = Path()
                    let a = CGPoint(x: coast.edgeX(at: y - length / 2) + sign * distance, y: y - length / 2)
                    let b = CGPoint(x: coast.edgeX(at: y + length / 2) + sign * distance, y: y + length / 2)
                    let control = CGPoint(x: coast.edgeX(at: y) + sign * (distance - 5 * scale), y: y)
                    crest.move(to: a); crest.addQuadCurve(to: b, control: control)
                    c.stroke(crest, with: .color(Color(dinoHex: 0xE4FFF1).opacity(Double(fade) * (0.15 + Double(seed % 4) * 0.025))),
                             style: StrokeStyle(lineWidth: (seed % 3 == 0 ? 1.15 : 0.75) * scale, lineCap: .round))
                    if seed % 3 == 0 {
                        c.stroke(crest.offsetBy(dx: sign * 5 * scale, dy: 2 * scale),
                                 with: .color(Color(dinoHex: 0xB2E7DC).opacity(Double(fade) * 0.11)),
                                 style: StrokeStyle(lineWidth: 0.65 * scale, lineCap: .round))
                    }
                }
            }
        }
    }
}

/// Flocks cross the open lanes between stones and rest on actual scenery surfaces.
private struct PirateGullFlocks: Sendable {
    struct Landing: Sendable {
        let point: CGPoint
        let structure: Bool
    }
    struct Flock: Sendable {
        let id: Int
        let laneY: CGFloat
        let left: [Landing]
        let right: [Landing]
        let crossing: Double
        var count: Int { fliesThrough ? 6 : min(left.count, right.count) }
        var leftRest: Double { 6.5 + Double(id % 3) * 1.1 }
        var rightRest: Double { 7.5 + Double(id % 4) * 0.8 }
        var fliesThrough: Bool { id % 4 == 1 || id % 4 == 3 }
    }
    struct Pose: Identifiable, Sendable {
        let id: Int
        var point: CGPoint
        let size: CGFloat
        let angle: Double
        let facing: CGFloat
        let phase: Double
        var flight: CGFloat
        let cruising: Bool
        let visible: Bool
        let fliesThrough: Bool
        let wingTime: Double
        let wingBeat: CGFloat
        var radius: CGFloat { 38 * size }
    }
    let scale: CGFloat
    let flocks: [Flock]
    let nodes: [(point: CGPoint, radius: CGFloat)]
    let width: CGFloat
    let cacheKey: String
    static let period: Double = 68

    private static func noise(_ seed: Int) -> Double {
        var n = UInt32(truncatingIfNeeded: seed) &+ 0x9E3779B9
        n = (n ^ (n >> 16)) &* 0x7FEB352D
        n = (n ^ (n >> 15)) &* 0x846CA68B
        return Double((n ^ (n >> 16)) & 0x00FFFFFF) / 16_777_215
    }

    /// Elliptical room for bodies at rest, and open wings during flight.
    static func space(_ a: Pose, _ b: Pose) -> CGSize {
        let open = max(a.flight, b.flight), size = a.size + b.size
        return CGSize(width: (24 + open * 5) * size, height: (12 + open * 13) * size)
    }

    init(sea: PirateSeaGeometry) {
        let layout = sea.layout, scale = layout.scale
        self.scale = scale
        self.width = layout.width
        self.cacheKey = "\(layout.width):\(layout.height):\(layout.routeOffset)"
        let routeWidth = min(layout.width, 600) - 36
        let nodes = WorldRouteTrail.chapterPositions.enumerated().map { index, fraction in
            (point: CGPoint(x: (layout.width - routeWidth) / 2 + routeWidth * fraction,
                            y: 80 + CGFloat(index) * 175), radius: CGFloat(index == 9 ? 45 : 36))
        }
        self.nodes = nodes
        func clearsStones(_ point: CGPoint) -> Bool {
            nodes.allSatisfy { hypot(point.x - $0.point.x, point.y - $0.point.y) > $0.radius + 22 * scale + 12 }
        }
        func safeApproach(_ point: CGPoint, lane: CGFloat) -> Bool {
            guard point.x > 20 * scale && point.x < layout.width - 20 * scale,
                  abs(point.x - layout.centerX(at: lane)) > max(40, 45 * scale) else { return false }
            return (0...16).allSatisfy { index in
                let t = CGFloat(index) / 16
                return [-8.0, 8].allSatisfy { offset in
                    let y = (point.y - 5 * scale) * (1 - t) + (lane + CGFloat(offset) * scale) * t
                    return clearsStones(CGPoint(x: point.x, y: y))
                }
            }
        }
        var surfaces: [Landing] = []
        func add(_ point: CGPoint) { surfaces.append(Landing(point: point, structure: true)) }
        for jetty in PirateCoastLayout.jetties(layout: layout) {
            for y: CGFloat in [-15, 19] {
                add(jetty.position(.init(x: -42, y: y - 26)))
                add(jetty.position(.init(x: 43, y: y - 38)))
            }
        }
        let sites = PirateCoastLayout.sites(layout: layout)
        for site in sites {
            func at(_ local: CGPoint) -> CGPoint {
                CGPoint(x: site.point.x + local.x * site.size, y: site.point.y + local.y * site.size)
            }
            switch site.id {
            case 0, 4:
                for t: CGFloat in [0.06, 0.25, 0.44, 0.63, 0.82, 0.97] {
                    add(at(.init(x: -8 + (-43 + 91 * t) * 0.96, y: 1 + (-46 - 10 * t) * 0.96)))
                }
            case 3, 7:
                add(at(.init(x: 9, y: -53))); add(at(.init(x: 22, y: -52)))
                add(at(.init(x: -27, y: 13 - 31 * 0.91)))
                add(at(.init(x: -3, y: 17 - 31 * 0.72)))
            case 6:
                add(at(.init(x: 39, y: 13 - 31 * 0.79)))
            case 8:
                for x: CGFloat in [-19, 0, 19] { add(at(.init(x: -1 + x * 1.22, y: 12 - 77 * 1.22))) }
            default: break
            }
        }
        // Resting bodies must be clear of palm leaves, including the opposite bank.
        var crowns: [CGRect] = []
        func crown(at point: CGPoint, size: CGFloat, mirrored: Bool = false) {
            crowns.append(CGRect(x: point.x + (mirrored ? -102 : -72) * size,
                                 y: point.y - 200 * size, width: 174 * size, height: 132 * size))
        }
        for site in sites where [0, 2, 4, 6].contains(site.id) {
            let camp = site.id % 4 == 0
            crown(at: CGPoint(x: site.point.x + (camp ? 26 : -27) * site.size,
                              y: site.point.y + (camp ? -8 : -3) * site.size),
                  size: site.size * (camp ? 0.94 : 0.83))
        }
        for index in [0, 3, 6] {
            let right = index % 4 == 0 || index % 4 == 3
            let base = layout.position(CGPoint(x: right ? 7 * scale : layout.width - 7 * scale,
                                               y: 273 + CGFloat(index) * 175))
            crown(at: CGPoint(x: base.x, y: base.y - 4 * scale), size: scale * 0.79, mirrored: !right)
        }
        let rocks = PirateCoastLayout.landRocks(layout: layout)
        for rock in rocks where rock.size >= 0.43 * scale {
            add(.init(x: rock.point.x - rock.size, y: rock.point.y - 47.5 * rock.size))
        }
        var prepared: [Flock] = []
        var reserved: [CGPoint] = []
        for gap in 0..<9 {
            let lane = 167.5 + CGFloat(gap) * 175
            let center = layout.centerX(at: lane)
            if gap % 4 == 1 || gap % 4 == 3 {
                prepared.append(Flock(id: gap, laneY: lane, left: [], right: [], crossing: 0))
                continue
            }
            let count = gap % 2 == 0 ? 5 : 6
            func landings(right: Bool) -> [Landing] {
                var selected: [Landing] = []
                let candidates = surfaces.filter {
                    abs($0.point.y - lane) < 156 * scale && ($0.point.x > center) == right
                }.sorted { abs($0.point.y - lane) < abs($1.point.y - lane) }
                func accept(_ candidate: Landing) {
                    let body = CGRect(x: candidate.point.x - 14 * scale, y: candidate.point.y - 21 * scale,
                                      width: 28 * scale, height: 23 * scale)
                    guard selected.count < count, safeApproach(candidate.point, lane: lane),
                          !crowns.contains(where: { $0.intersects(body) }),
                          (selected.map(\.point) + reserved).allSatisfy({ point in
                              hypot((point.x - candidate.point.x) / (25 * scale),
                                    (point.y - candidate.point.y) / (14 * scale)) > 1
                          }) else { return }
                    selected.append(candidate)
                }
                for candidate in candidates { accept(candidate) }
                if selected.count == count { return selected }
                // A stable scatter leaves loose clusters rather than rows on the beach.
                for candidate in 0..<640 {
                    if selected.count == count { return selected }
                    let seed = gap * 1009 + candidate * 7 + (right ? 503 : 0)
                    let y = lane + CGFloat(Self.noise(seed + 19) * 236 - 118) * scale
                    let distance = CGFloat(53 + Self.noise(seed + 47) * 178) * scale
                    let point = CGPoint(x: layout.centerX(at: y) + (right ? distance : -distance), y: y)
                    guard !sea.coasts.contains(where: { coast in
                        [-4.0, 0, 4].contains { dx in
                            coast.water.contains(CGPoint(x: point.x + CGFloat(dx) * scale, y: point.y))
                        }
                    }) else { continue }
                    let underStructure = sites.contains { site in
                        CGRect(x: site.point.x - 67 * site.size, y: site.point.y - 120 * site.size,
                               width: 132 * site.size, height: 158 * site.size).contains(point)
                    }
                    guard !underStructure,
                          !rocks.contains(where: { $0.bounds.insetBy(dx: -9 * scale, dy: -7 * scale).contains(point) }) else { continue }
                    accept(Landing(point: point, structure: false))
                }
                return selected
            }
            let left = landings(right: false), right = landings(right: true)
            reserved += Array(left.prefix(min(left.count, right.count))).map(\.point)
            reserved += Array(right.prefix(min(left.count, right.count))).map(\.point)
            let width = zip(left, right).map { abs($1.point.x - $0.point.x) }.max() ?? 240 * scale
            prepared.append(Flock(id: gap, laneY: lane, left: left, right: right,
                                  crossing: max(3.4, Double(width) / 62) + 2.1))
        }
        flocks = prepared
    }

    /// Groups share overlapping events, not a common departure clock. Passers-by
    /// enter as one group lands; a third departs midway, followed from the far side.
    private func timing(for flock: Flock) -> (phase: Double, departure: Double, passing: Double) {
        let block = flock.id / 4, first = flocks[block * 4]
        let passage = Double(width + 120 * scale) / Double(62 * scale)
        let firstLanding = first.leftRest + 1.5 + first.crossing
        let secondEntry = firstLanding - 2.2
        let thirdDeparture = secondEntry + passage * 0.45
        let third = flocks[min(block * 4 + 2, flocks.count - 1)]
        let fourthEntry = thirdDeparture + third.crossing - 2.0
        let departure: Double
        switch flock.id % 4 {
        case 1: departure = secondEntry
        case 2: departure = thirdDeparture
        case 3: departure = fourthEntry
        default: departure = first.leftRest - 0.4
        }
        return ([0.0, 7.6, 18.2][block], departure, passage)
    }

    /// Every bird has its own timing and a gently bending route within the open gap.
    func poses(time: Double, track: PirateGullMotionTrack) -> [Pose] {
        var poses = rawPoses(time: time)
        let state = track.sample(time: time)
        for index in poses.indices {
            poses[index].point = state[index].point
            poses[index].flight = state[index].flight
        }
        return poses
    }

    func rawPoses(time: Double) -> [Pose] {
        let unwrappedTime = time
        let time = (time.truncatingRemainder(dividingBy: Self.period) + Self.period).truncatingRemainder(dividingBy: Self.period)
        func smooth(_ t: Double) -> CGFloat {
            let t = CGFloat(min(1, max(0, t))); return t * t * (3 - 2 * t)
        }
        func mix(_ a: CGPoint, _ b: CGPoint, _ t: CGFloat) -> CGPoint {
            CGPoint(x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t)
        }
        func cruisePoint(_ u: CGFloat, start: CGPoint, end: CGPoint, flock: Flock, seed: Int, phase: Double, bias: CGFloat) -> CGPoint {
            // Smooth changes in pace vary independently from the wingbeat.
            let progress = u + sin(u * .pi * 2) * CGFloat(0.018 + Self.noise(seed + 71) * 0.024)
            let x = start.x + (end.x - start.x) * progress
            let arc = sin(u * .pi) * CGFloat(sin(Double(flock.id) * 1.73 + time * (.pi * 2 / Self.period)) * 14)
            let drift = CGFloat(sin(Double(u) * 5.3 + phase) * 2.5 + sin(time * (.pi * 12 / Self.period) + phase * 1.7) * 1.5)
            let y = flock.laneY + (bias + arc + drift) * scale
            let upper = nodes[flock.id], lower = nodes[flock.id + 1]
            let clearance = 22 * scale + 13
            let topRadius = upper.radius + clearance, bottomRadius = lower.radius + clearance
            let topDX = abs(x - upper.point.x), bottomDX = abs(x - lower.point.x)
            let low = upper.point.y + sqrt(max(0, topRadius * topRadius - topDX * topDX)) + 1
            let high = lower.point.y - sqrt(max(0, bottomRadius * bottomRadius - bottomDX * bottomDX)) - 1
            let middle = (low + high) / 2, room = max(2, (high - low) / 2)
            return CGPoint(x: x, y: middle + room * CGFloat(tanh(Double((y - middle) / room))))
        }
        var birds: [Pose] = []
        for flock in flocks {
            let timing = timing(for: flock)
            let clock = time + timing.phase
            let t = clock.truncatingRemainder(dividingBy: Self.period)
            for bird in 0..<flock.count {
                let id = flock.id * 10 + bird, seed = id * 137 + 31
                let size = scale * CGFloat(0.45 + Self.noise(seed) * 0.08)
                let phase = Self.noise(seed + 11) * .pi * 2
                let variation = Self.noise(seed + 701)
                let slots = [0.0, 0.57, 1.48, 1.90, 2.85, 3.39]
                let order = [0, 3, 1, 5, 2, 4][(bird + flock.id) % 6]
                let reverseOrder = [2, 5, 0, 4, 1, 3][(bird + flock.id) % 6]
                let leaveLeft = timing.departure + slots[order] + (variation - 0.5) * 0.24
                let outwardDuration = flock.crossing * (0.92 + Self.noise(seed + 23) * 0.16)
                let leaveRight = timing.departure + flock.crossing + flock.rightRest
                    + slots[reverseOrder] + (0.5 - variation) * 0.24
                let returnDuration = min(flock.crossing * (0.92 + Self.noise(seed + 37) * 0.16), Self.period - leaveRight - 0.7)
                let bias = CGFloat([-23.0, 7, -3, 24, -13, 15][(bird + flock.id) % 6] + Self.noise(seed + 97) * 3 - 1.5)
                let left = flock.fliesThrough ? CGPoint.zero : flock.left[bird].point
                let right = flock.fliesThrough ? CGPoint.zero : flock.right[bird].point
                var point: CGPoint, flight: CGFloat = 0, facing: CGFloat, bank: Double = 0, cruising = false
                var visible = true
                if flock.fliesThrough {
                    let outward = flock.id % 4 == 1
                    // Two loose passages per long round, reset entirely beyond the viewport.
                    let starts = [timing.departure, timing.departure + Self.period * 0.53 + Self.noise(seed + 131) * 1.4]
                    let duration = timing.passing * (0.93 + Self.noise(seed + 23) * 0.14)
                    let elapsed = starts.map { start in
                        (t - start - slots[order] + Self.period * 2).truncatingRemainder(dividingBy: Self.period)
                    }.min()!
                    visible = elapsed < duration
                    let u = CGFloat(visible ? elapsed / duration : 0)
                    let start = CGPoint(x: outward ? -60 * scale : width + 60 * scale, y: flock.laneY)
                    let end = CGPoint(x: outward ? width + 60 * scale : -60 * scale, y: flock.laneY)
                    point = cruisePoint(u, start: start, end: end, flock: flock, seed: seed, phase: phase, bias: bias)
                    let before = cruisePoint(max(0, u - 0.015), start: start, end: end, flock: flock, seed: seed, phase: phase, bias: bias)
                    let after = cruisePoint(min(1, u + 0.015), start: start, end: end, flock: flock, seed: seed, phase: phase, bias: bias)
                    bank = min(0.2, max(-0.2, atan2(Double(after.y - before.y), Double(abs(after.x - before.x))) * 0.45))
                    flight = 1; cruising = true; facing = outward ? 1 : -1
                } else if t < leaveLeft || t >= leaveRight + returnDuration {
                    point = .init(x: left.x, y: left.y - 10 * size)
                    facing = 1
                } else if t >= leaveLeft + outwardDuration && t < leaveRight {
                    point = .init(x: right.x, y: right.y - 10 * size)
                    facing = t - leaveLeft - outwardDuration < 0.9 ? 1 : -1
                } else {
                    let outward = t < leaveLeft + outwardDuration
                    let elapsed = outward ? t - leaveLeft : t - leaveRight
                    let duration = outward ? outwardDuration : returnDuration
                    let from = outward ? left : right, to = outward ? right : left
                    let start = CGPoint(x: from.x, y: from.y - 10 * size)
                    let end = CGPoint(x: to.x, y: to.y - 10 * size)
                    let routeSeed = seed + (outward ? 0 : 401)
                    let inward = outward ? CGFloat(1) : -1
                    let gateOffset = min(34 * scale, abs(end.x - start.x) * 0.18)
                    let cruiseStart = CGPoint(x: start.x + inward * gateOffset, y: start.y)
                    let cruiseEnd = CGPoint(x: end.x - inward * gateOffset, y: end.y)
                    let first = cruisePoint(0, start: cruiseStart, end: cruiseEnd, flock: flock, seed: routeSeed, phase: phase, bias: bias)
                    let last = cruisePoint(1, start: cruiseStart, end: cruiseEnd, flock: flock, seed: routeSeed, phase: phase, bias: bias)
                    let departure = min(duration * 0.30, max(0.95, Double(abs(first.y - start.y) / (95 * scale)) + 0.45))
                    let arrival = min(duration * 0.30, max(0.95, Double(abs(last.y - end.y) / (90 * scale)) + 0.45))
                    if elapsed < departure {
                        let u = smooth(elapsed / departure)
                        point = mix(start, first, u)
                        point.x += sin(u * .pi) * CGFloat(Self.noise(seed + 43) * 8 - 4) * scale
                    } else if elapsed > duration - arrival {
                        let u = smooth((elapsed - duration + arrival) / arrival)
                        point = mix(last, end, u)
                        point.x += sin(u * .pi) * CGFloat(Self.noise(seed + 53) * 8 - 4) * scale
                    } else {
                        cruising = true
                        let u = CGFloat((elapsed - departure) / (duration - departure - arrival))
                        point = cruisePoint(u, start: cruiseStart, end: cruiseEnd, flock: flock, seed: routeSeed, phase: phase, bias: bias)
                        let before = cruisePoint(max(0, u - 0.015), start: cruiseStart, end: cruiseEnd, flock: flock, seed: routeSeed, phase: phase, bias: bias)
                        let after = cruisePoint(min(1, u + 0.015), start: cruiseStart, end: cruiseEnd, flock: flock, seed: routeSeed, phase: phase, bias: bias)
                        bank = min(0.20, max(-0.20, atan2(Double(after.y - before.y), Double(abs(after.x - before.x))) * 0.45))
                        bank += sin(unwrappedTime * (0.71 + Self.noise(seed + 61) * 0.4) + phase) * 0.035
                    }
                    facing = outward ? 1 : -1
                    flight = min(smooth(elapsed / 0.55), smooth((duration - elapsed) / 0.7))
                }
                let wingTime = unwrappedTime * (0.83 + Self.noise(seed + 101) * 0.34) + sin(unwrappedTime * 0.31 + phase) * 0.32
                let glide = CGFloat(0.30 + 0.70 * pow((sin(unwrappedTime * 0.63 + phase) + 1) / 2, 0.7))
                birds.append(Pose(id: id, point: point, size: size, angle: bank,
                                  facing: facing, phase: phase, flight: flight, cruising: cruising, visible: visible, fliesThrough: flock.fliesThrough,
                                  wingTime: wingTime, wingBeat: cruising ? glide : 1))
            }
        }
        return birds
    }

    func clearOfStones(_ point: CGPoint, radius: CGFloat, allowOffscreen: Bool = false) -> CGPoint {
        var point = point
        for node in nodes {
            let dx = point.x - node.point.x, dy = point.y - node.point.y
            let distance = max(0.001, hypot(dx, dy)), boundary = node.radius + radius + 12
            if distance < boundary + 7 * scale {
                let overlap = boundary + 7 * scale - distance
                let push = overlap * overlap / (overlap + 7 * scale)
                point.x += dx / distance * push; point.y += dy / distance * push
            }
        }
        if !allowOffscreen { point.x = max(16 * scale, min(width - 16 * scale, point.x)) }
        return point
    }

}

/// A small cached flight track lets steering keep momentum instead of teleporting
/// neighbours apart. Four warm-up rounds settle the periodic flock before playback.
private final class PirateGullMotionTrack: Sendable {
    struct State: Sendable { var point: CGPoint; var flight: CGFloat; let visible: Bool }
    private let frames: [[State]]
    var frameCount: Int { frames.count }
#if DEBUG
    let preparationMilliseconds: Double
#endif
    private static let steps = Int(PirateGullFlocks.period * 16)
    private static let interval: CGFloat = 1 / 16

    init(plan: PirateGullFlocks) throws {
        assert(!Thread.isMainThread, "Gull flight preparation must never run on the scrolling thread")
#if DEBUG
        let preparationStarted = ProcessInfo.processInfo.systemUptime
        defer {
            if ProcessInfo.processInfo.environment["DINO_TEST_MAP_DIAGNOSTICS"] == "1" {
                print("MAP_GULL_PREPARATION milliseconds=\((ProcessInfo.processInfo.systemUptime - preparationStarted) * 1000) mainThread=\(Thread.isMainThread)")
            }
        }
#endif
        try Task.checkCancellation()
        let h = Self.interval, scale = plan.scale
        let targets = (0..<Self.steps).map { plan.rawPoses(time: Double($0) / 16) }
        let count = targets[0].count
        var positions = targets[0].map(\.point)
        var velocities = Array(repeating: CGPoint.zero, count: count)
        var recorded: [[State]] = []
        func limited(_ vector: CGPoint, _ maximum: CGFloat) -> CGPoint {
            let length = max(0.001, hypot(vector.x, vector.y)), factor = min(1, maximum / length)
            return CGPoint(x: vector.x * factor, y: vector.y * factor)
        }
        for round in 0..<8 {
            let start = positions
            recorded.removeAll(keepingCapacity: true)
            for frame in 0..<Self.steps {
                try Task.checkCancellation()
                let target = targets[frame], next = targets[(frame + 1) % Self.steps]
                let before = positions
                var forces = Array(repeating: CGPoint.zero, count: count)
                var mobility = Array(repeating: CGFloat(0), count: count)
                var effective = target
                for index in 0..<count {
                    let error = CGPoint(x: next[index].point.x - positions[index].x,
                                        y: next[index].point.y - positions[index].y)
                    let distance = hypot(error.x, error.y)
                    let opening = targets[(frame + 6) % Self.steps][index].flight
                    effective[index].flight = max(target[index].flight, opening * 0.9, min(0.45, distance / (18 * scale)))
                    let active = target[index].visible && next[index].visible
                    mobility[index] = active && (target[index].flight > 0.02 || distance > 3 * scale) ? 1 : 0
                    if !active { positions[index] = next[index].point; velocities[index] = .zero }
                    let feed = CGPoint(x: (next[index].point.x - target[index].point.x) / h,
                                       y: (next[index].point.y - target[index].point.y) / h)
                    forces[index] = CGPoint(x: (feed.x + error.x * 1.8 - velocities[index].x) * 5,
                                            y: (feed.y + error.y * 1.8 - velocities[index].y) * 5)
                }
                for a in 0..<count {
                    for b in (a + 1)..<count {
                        guard target[a].visible, target[b].visible, mobility[a] + mobility[b] > 0,
                              max(target[a].flight, target[b].flight) > 0.02 else { continue }
                        let room = PirateGullFlocks.space(effective[a], effective[b])
                        let nx = (positions[a].x - positions[b].x) / room.width
                        let ny = (positions[a].y - positions[b].y) / room.height
                        let distance = max(0.001, hypot(nx, ny))
                        guard distance < 2.4 else { continue }
                        let pressure = pow(2.4 - distance, 2) * 280 * scale
                        var fx = nx / distance * pressure, fy = ny / distance * pressure
                        let vx = velocities[a].x - velocities[b].x, vy = velocities[a].y - velocities[b].y
                        if abs(vx) >= abs(vy) {
                            fy += (ny >= 0 ? 1 : -1) * pressure * 0.7
                        } else {
                            fx += (nx >= 0 ? 1 : -1) * pressure * 0.7
                        }
                        forces[a].x += fx; forces[a].y += fy
                        forces[b].x -= fx; forces[b].y -= fy
                    }
                }
                for index in 0..<count {
                    if mobility[index] == 0 {
                        positions[index] = next[index].point; velocities[index] = .zero
                    } else {
                        let force = limited(forces[index], 400 * scale)
                        velocities[index].x += force.x * h; velocities[index].y += force.y * h
                        velocities[index] = limited(velocities[index], 135 * scale)
                        positions[index].x += velocities[index].x * h; positions[index].y += velocities[index].y * h
                    }
                }
                // Small contact corrections supplement the anticipatory steering.
                for _ in 0..<16 {
                    for a in 0..<count {
                        for b in (a + 1)..<count {
                            let weight = mobility[a] + mobility[b]
                            guard target[a].visible, target[b].visible, weight > 0 else { continue }
                            let room = PirateGullFlocks.space(effective[a], effective[b])
                            var nx = (positions[a].x - positions[b].x) / room.width
                            var ny = (positions[a].y - positions[b].y) / room.height
                            if abs(nx) + abs(ny) < 0.001 { nx = 0.01; ny = 0.01 }
                            let distance = max(0.001, hypot(nx, ny))
                            let buffer: CGFloat = max(target[a].flight, target[b].flight) < 0.02 ? 1.02 : 1.65
                            guard distance < buffer else { continue }
                            let amount = min(0.12, (buffer - distance) * 0.68)
                            let dx = nx / distance * room.width * amount, dy = ny / distance * room.height * amount
                            positions[a].x += dx * mobility[a] / weight; positions[a].y += dy * mobility[a] / weight
                            positions[b].x -= dx * mobility[b] / weight; positions[b].y -= dy * mobility[b] / weight
                        }
                    }
                    for index in 0..<count where mobility[index] > 0 {
                        positions[index] = plan.clearOfStones(positions[index], radius: target[index].radius, allowOffscreen: target[index].fliesThrough)
                    }
                }
                var states: [State] = []
                for index in 0..<count {
                    let displacement = limited(CGPoint(x: positions[index].x - before[index].x,
                                                       y: positions[index].y - before[index].y), 195 * scale * h)
                    if mobility[index] > 0 {
                        positions[index] = plan.clearOfStones(CGPoint(x: before[index].x + displacement.x,
                                                                     y: before[index].y + displacement.y), radius: target[index].radius, allowOffscreen: target[index].fliesThrough)
                    }
                    velocities[index] = CGPoint(x: displacement.x / h, y: displacement.y / h)
                    let distance = hypot(positions[index].x - next[index].point.x, positions[index].y - next[index].point.y)
                    let flight = max(next[index].flight, min(0.45, max(0, distance / (18 * scale) - 0.03)))
                    states.append(State(point: positions[index], flight: flight, visible: next[index].visible))
                }
                recorded.append(states)
            }
            let closure = zip(start, positions).map { hypot($0.x - $1.x, $0.y - $1.y) }.max() ?? 0
            if round >= 3 && closure < 1.2 * scale { break }
        }
        // Samples follow integration by one tick; rotate so phase zero is exact.
        frames = [recorded.last!] + recorded.dropLast()
#if DEBUG
        preparationMilliseconds = (ProcessInfo.processInfo.systemUptime - preparationStarted) * 1000
#endif
    }

    func sample(time: Double) -> [State] {
        let phase = (time.truncatingRemainder(dividingBy: PirateGullFlocks.period) + PirateGullFlocks.period).truncatingRemainder(dividingBy: PirateGullFlocks.period) * 16
        let index = Int(phase), amount = CGFloat(phase - Double(index))
        let first = frames[index % frames.count], next = frames[(index + 1) % frames.count]
        return first.indices.map { bird in
            // Invisible flybys reset offscreen; never interpolate that reset across the map.
            let blend = first[bird].visible == next[bird].visible ? amount : (first[bird].visible ? 0 : 1)
            return State(point: CGPoint(x: first[bird].point.x + (next[bird].point.x - first[bird].point.x) * blend,
                                 y: first[bird].point.y + (next[bird].point.y - first[bird].point.y) * blend),
                  flight: first[bird].flight + (next[bird].flight - first[bird].flight) * blend,
                  visible: first[bird].visible || next[bird].visible)
        }
    }
}

/// The collision solver runs on this actor's executor, never in a TimelineView.
/// Serial preparation avoids competing simulations during rotation; cancelled
/// requests stop between integration steps and completed sizes remain reusable.
private actor PirateGullFlightCache {
    static let shared = PirateGullFlightCache()
    struct Prepared: Sendable {
        let key: String
        let flocks: PirateGullFlocks
        let track: PirateGullMotionTrack
        let preparedOnMainThread: Bool
    }
    private var flights: [String: Prepared] = [:]
    private var order: [String] = []

    static func key(size: CGSize, routeOffset: CGFloat) -> String {
        "\(size.width):\(size.height):\(routeOffset)"
    }

    func flight(size: CGSize, routeOffset: CGFloat) throws -> Prepared {
        try Task.checkCancellation()
        let key = Self.key(size: size, routeOffset: routeOffset)
        if let prepared = flights[key] {
            order.removeAll { $0 == key }; order.append(key)
            return prepared
        }
        let layout = WorldSceneryLayout(width: size.width, height: size.height, routeOffset: routeOffset)
        let flocks = PirateGullFlocks(sea: PirateSeaGeometry(layout: layout))
        let prepared = Prepared(key: key, flocks: flocks, track: try PirateGullMotionTrack(plan: flocks),
                                preparedOnMainThread: Thread.isMainThread)
        flights[key] = prepared
        order.append(key)
        if order.count > 6 { flights.removeValue(forKey: order.removeFirst()) }
        return prepared
    }
}

struct PirateCoastFlights: View {
    let routeOffset: CGFloat
    let viewportHeight: CGFloat
    var fixedTime: TimeInterval? = nil
    var frozen = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.dinoMapAnimationEpoch) private var animationEpoch
    @State private var viewport = CGRect.zero
    @State private var prepared: PirateGullFlightCache.Prepared?

    var body: some View {
        GeometryReader { geometry in
            let key = PirateGullFlightCache.key(size: geometry.size, routeOffset: routeOffset)
            TimelineView(.animation(minimumInterval: 1.0 / 20,
                                    paused: prepared?.key != key || fixedTime != nil || frozen || reduceMotion || viewport.isEmpty || scenePhase != .active)) { timeline in
                let time = frozen || reduceMotion ? 0 : (fixedTime ?? timeline.date.timeIntervalSince(animationEpoch ?? Date(timeIntervalSinceReferenceDate: 0)))
                ZStack(alignment: .topLeading) {
                    if let prepared, prepared.key == key, fixedTime != nil || !viewport.isEmpty {
                        ForEach(prepared.flocks.poses(time: time, track: prepared.track)) { pose in
                            let point = CGPoint(x: pose.point.x, y: pose.point.y + routeOffset)
                            let frame = CGRect(x: point.x - pose.radius, y: point.y - pose.radius,
                                               width: pose.radius * 2, height: pose.radius * 2)
                            if pose.visible && (fixedTime != nil || frame.intersects(viewport)) {
                                Canvas { context, _ in
                                    var c = context; c.translateBy(x: pose.radius, y: pose.radius)
                                    c.rotate(by: .radians(pose.angle)); c.scaleBy(x: pose.size * pose.facing, y: pose.size)
                                    PirateGullPainter(context: c).gull(time: pose.wingTime, phase: pose.phase, flight: pose.flight, beat: pose.wingBeat)
                                }.frame(width: frame.width, height: frame.height).position(x: frame.midX, y: frame.midY)
                            }
                        }
                    }
                }.frame(width: geometry.size.width, height: geometry.size.height, alignment: .topLeading)
            }
            .task(id: key, priority: .utility) {
                guard geometry.size.width > 0, geometry.size.height > 0 else { return }
                do {
                    let flight = try await PirateGullFlightCache.shared.flight(size: geometry.size, routeOffset: routeOffset)
                    try Task.checkCancellation()
                    prepared = flight
#if DEBUG
                    DinoMapArtworkCache.shared.recordGullPreparation(frames: flight.track.frameCount,
                        milliseconds: flight.track.preparationMilliseconds, onMainThread: flight.preparedOnMainThread)
#endif
                } catch { /* Leaving the map or resizing cancels obsolete preparation. */ }
            }
            .readGeometry(for: CGRect.self) { proxy in
                DinoMapViewport.preparedAnimationBounds(frame: proxy.frame(in: .named("adventure.map.viewport")), viewportHeight: viewportHeight)
            } action: { viewport = $0 }
        }.clipped().allowsHitTesting(false).accessibilityHidden(true)
    }
}

private struct PirateGullPainter {
    let context: GraphicsContext

    func gull(time: Double, phase: Double, flight: CGFloat = 1, beat: CGFloat = 1) {
        let flap = CGFloat(sin(time * 4.7 + phase)) * beat
        let lift = 2 * (1 - flight) + (-10 - flap * 13) * flight
        let feather: UInt32 = 0xFBFAEE, tip: UInt32 = 0x596D72
        func fill(_ path: Path, _ color: UInt32) { context.fill(path, with: .color(Color(dinoHex: color))) }
        func wing(root: CGPoint, span: CGFloat, lift: CGFloat) -> Path {
            var p = Path(); p.move(to: root)
            p.addCurve(to: .init(x: root.x + span, y: lift),
                       control1: .init(x: root.x + span * 0.28, y: lift - 7),
                       control2: .init(x: root.x + span * 0.78, y: lift - 4))
            p.addQuadCurve(to: .init(x: root.x + span * 0.60, y: lift + 2 + 6 * flight),
                           control: .init(x: root.x + span * 0.84, y: lift + 2 + 5 * flight))
            p.addQuadCurve(to: .init(x: root.x + 2, y: root.y + 4),
                           control: .init(x: root.x + span * 0.23, y: root.y + 1))
            p.closeSubpath(); return p
        }
        func wingTip(root: CGPoint, span: CGFloat, lift: CGFloat) {
            var p = Path(); p.move(to: .init(x: root.x + span, y: lift))
            p.addQuadCurve(to: .init(x: root.x + span * 0.72, y: lift + 2 + 5 * flight),
                           control: .init(x: root.x + span * 0.89, y: lift + 1 + 5 * flight))
            p.addLine(to: .init(x: root.x + span * 0.68, y: lift + 0.8)); p.closeSubpath()
            fill(p, tip)
        }
        // Folded wings lie along the back. Both open together on departure.
        let farSpan = -13 - 9 * flight, nearSpan = -13 + 35 * flight
        let farRoot = CGPoint(x: -4, y: -1)
        fill(wing(root: farRoot, span: farSpan, lift: lift + 1), feather)
        wingTip(root: farRoot, span: farSpan, lift: lift + 1)
        var tail = Path(); tail.addLines([.init(x: -8, y: 0), .init(x: -21, y: -1), .init(x: -18, y: 3), .init(x: -22, y: 7), .init(x: -8, y: 5)]); tail.closeSubpath()
        fill(tail, feather)
        if flight < 0.85 {
            let extensionAmount = min(1, (0.85 - flight) / 0.5)
            for x: CGFloat in [-4, 4] {
                var leg = Path(); leg.move(to: .init(x: x, y: 4))
                leg.addLine(to: .init(x: x + 1, y: 5 + 5 * extensionAmount))
                leg.addLine(to: .init(x: x + 5, y: 5 + 5 * extensionAmount))
                context.stroke(leg, with: .color(Color(dinoHex: 0xCB9B4B)),
                               style: StrokeStyle(lineWidth: 1.2, lineCap: .round))
            }
        }
        context.fill(Path(ellipseIn: CGRect(x: -11, y: -4, width: 25, height: 10)),
                     with: .linearGradient(Gradient(colors: [Color(dinoHex: feather), Color(dinoHex: 0xE7EDE1)]),
                                           startPoint: .init(x: 0, y: -4), endPoint: .init(x: 0, y: 6)))
        let nearRoot = CGPoint(x: -3, y: 1)
        fill(wing(root: nearRoot, span: nearSpan, lift: lift + 2), feather)
        wingTip(root: nearRoot, span: nearSpan, lift: lift + 2)
        fill(Path(ellipseIn: CGRect(x: 10, y: -5, width: 8, height: 9)), feather)
        var beak = Path(); beak.addLines([.init(x: 17, y: -2), .init(x: 23, y: 0), .init(x: 17, y: 1.7)]); beak.closeSubpath()
        fill(beak, 0xD8A34D)
        fill(Path(ellipseIn: CGRect(x: 14.8, y: -2.5, width: 1.6, height: 1.7)), 0x2C4952)
    }
}

/// Courts, bridges and stair landings share their endpoints. The side walks
/// make a complete circuit through each royal garden, separate from the game trail.
private struct CastleKingdomLayout {
    enum Kind { case clockTower, statue, stairs, fountain, palace, gate }
    static let innerWalkOffset: CGFloat = -28
    static let outerWalkOffset: CGFloat = 34
    static let innerHedgeOffset: CGFloat = -41
    static let middleLandingWidth: CGFloat = 64
    static let middleLandingDepth: CGFloat = 24
    static let bridgeBackEdge: CGFloat = -13
    static let bridgeFrontEdge: CGFloat = 11
    static let avenueHedgeHeight: CGFloat = 11
    static let avenueHedgeWidth: CGFloat = 9
    struct Landmark {
        let kind: Kind
        let point: CGPoint
        let scale: CGFloat
        let right: Bool
        let halfWidth: CGFloat
        let rise: CGFloat
    }
    struct Flight {
        let top: CGPoint
        let bottom: CGPoint
        let scale: CGFloat
        var steps: Int { max(4, Int((bottom.y - top.y) / (8 * scale))) }
        func edge(_ t: CGFloat, side: CGFloat) -> CGPoint {
            let width = 22 * scale
            return CGPoint(x: top.x + (bottom.x - top.x) * t + side * width,
                           y: top.y + (bottom.y - top.y) * t)
        }
        var footprint: Path {
            let face = Path { p in
                p.addLines([edge(0, side: -1), edge(0, side: 1), edge(1, side: 1), edge(1, side: -1)])
                p.closeSubpath()
            }
            var result = face
            result.addPath(face.strokedPath(StrokeStyle(lineWidth: 12 * scale, lineJoin: .round)))
            return result
        }
    }
    struct District {
        let id: Int
        let right: Bool
        let upper: CGPoint
        let middle: CGPoint
        let lower: CGPoint
        let scale: CGFloat
        var flights: [Flight] {
            [Flight(top: CGPoint(x: upper.x, y: upper.y + 18 * scale),
                    bottom: CGPoint(x: middle.x, y: middle.y - CastleKingdomLayout.middleLandingDepth / 2 * scale), scale: scale),
             Flight(top: CGPoint(x: middle.x, y: middle.y + CastleKingdomLayout.middleLandingDepth / 2 * scale),
                    bottom: CGPoint(x: lower.x, y: lower.y - 18 * scale), scale: scale)]
        }
    }
    struct Crossing {
        let district: Int
        let upper: Bool
        let right: Bool
        let water: CGPoint
        let inner: CGPoint
        let entry: CGPoint
        let outer: CGPoint
        let scale: CGFloat
        let riverSlope: CGFloat

        var approachFloor: Path {
            let innerX = (inner.x - water.x) / scale, entryX = (entry.x - water.x) / scale
            let span = innerX - entryX
            let back = CastleKingdomLayout.bridgeBackEdge, front = CastleKingdomLayout.bridgeFrontEdge
            func point(_ t: CGFloat, _ y: CGFloat) -> CGPoint { .init(x: entryX + span * t, y: y) }
            var floor = Path(); floor.move(to: point(0.12, back - 6))
            floor.addCurve(to: point(1.1, back), control1: point(0.45, back - 6), control2: point(0.7, back))
            floor.addLine(to: point(1.1, front))
            floor.addCurve(to: point(0.12, front + 6), control1: point(0.7, front), control2: point(0.45, front + 6))
            floor.addQuadCurve(to: point(0, front + 3), control: point(0, front + 6))
            floor.addLine(to: point(0, back - 3))
            floor.addQuadCurve(to: point(0.12, back - 6), control: point(0, back - 6))
            floor.closeSubpath()
            return floor
        }
    }
    struct Fountain {
        let point: CGPoint
        let scale: CGFloat
        let depth: CGFloat
    }
    static let cascades: [(y: CGFloat, right: Bool)] = [(510, true), (1110, false)]

    func fountains(for district: District) -> [Fountain] {
        let sign: CGFloat = district.right ? 1 : -1, s = scale
        if district.id == 2 {
            return [Fountain(point: CGPoint(x: district.upper.x + sign * 12 * s, y: district.upper.y - 53 * s),
                             scale: s * 0.87, depth: district.lower.y + 41 * s)]
        }
        if district.id == 1 || district.id == 3 {
            return [Fountain(point: CGPoint(x: district.middle.x + sign * 94 * s, y: district.middle.y - 17 * s),
                             scale: s * 0.44, depth: district.lower.y + 41 * s)]
        }
        return []
    }
    let scenery: WorldSceneryLayout
    var scale: CGFloat { scenery.scale }

    var landmarks: [Landmark] {
        // The entrance clock remains a full-sized landmark on its own quay.
        let s = scale * 1.02, y: CGFloat = 225
        var x: CGFloat = 0
        for i in 0...32 {
            let localY = -238 + 266 * CGFloat(i) / 32
            x = max(x, scenery.centerX(at: y + localY * s) + (localY < -162 ? 34 : 53) * s + 53)
        }
        x = max(x, waterPoint(at: y, right: true).x + 60 * scale)
        return [Landmark(kind: .clockTower, point: CGPoint(x: x, y: y), scale: s,
                         right: true, halfWidth: 53, rise: 238)]
    }

    var districts: [District] {
        let s = scale
        let banks = [false, true].map { waterway(right: $0).strokedPath(StrokeStyle(lineWidth: 44 * s, lineCap: .round, lineJoin: .round)) }
        let plan: [(CGFloat, CGFloat, Bool)] = [(335, 590, false), (730, 930, true),
                                               (1035, 1290, false), (1415, 1595, true)]
        return plan.enumerated().map { index, row in
            let (topY, bottomY, right) = row, sign: CGFloat = right ? 1 : -1
            let midY = (topY + bottomY) / 2
            var top = waterPoint(at: topY, right: right), middle = waterPoint(at: midY, right: right)
            var bottom = waterPoint(at: bottomY, right: right)
            top.x += sign * 60 * s; middle.x += sign * 84 * s; bottom.x += sign * 60 * s
            // Query the actual stroked canal, including the rounded inside of
            // its exit bend. A tangent estimate misses the water just upstream
            // of a sharp turn. Cache each row while fitting the shared landings.
            var bankEdges: [CGFloat: CGFloat] = [:]
            func bankEdge(at y: CGFloat) -> CGFloat {
                if let cached = bankEdges[y] { return cached }
                var inside = waterPoint(at: y, right: right).x
                var outside = right ? max(scenery.width + 300, inside + 300 * s) : min(-300, inside - 300 * s)
                for _ in 0..<15 {
                    let x = (inside + outside) / 2
                    if banks[right ? 1 : 0].contains(CGPoint(x: x, y: y)) { inside = x } else { outside = x }
                }
                bankEdges[y] = outside
                return outside
            }
            func fitLanding(_ point: CGPoint, halfWidth: CGFloat = 33, halfDepth: CGFloat = 18) -> CGPoint {
                var shift: CGFloat = 0
                for i in 0...18 {
                    let y = point.y + (-halfDepth + CGFloat(i) * halfDepth / 9) * s
                    shift = max(shift, halfWidth * s - sign * (point.x - bankEdge(at: y)))
                }
                return CGPoint(x: point.x + sign * shift, y: point.y)
            }
            for _ in 0..<5 {
                top = fitLanding(top)
                middle = fitLanding(middle, halfWidth: Self.middleLandingWidth / 2 + 1, halfDepth: Self.middleLandingDepth / 2)
                bottom = fitLanding(bottom)
                // Keep each flight straight enough to read as a staircase.
                // Move the inner endpoint outwards; never pull a landing into water.
                let maxRun = ((bottomY - topY) / 2 - (18 + Self.middleLandingDepth / 2) * s) * 0.38
                if sign * (top.x - middle.x) > maxRun { middle.x = top.x - sign * maxRun }
                if sign * (middle.x - top.x) > maxRun { top.x = middle.x - sign * maxRun }
                if sign * (bottom.x - middle.x) > maxRun { middle.x = bottom.x - sign * maxRun }
                if sign * (middle.x - bottom.x) > maxRun { bottom.x = middle.x - sign * maxRun }
                for pair in [(0, 1), (1, 2)] {
                    let upper = pair.0 == 0 ? top : middle, lower = pair.1 == 1 ? middle : bottom
                    let a = CGPoint(x: upper.x, y: upper.y + (pair.0 == 0 ? 18 : Self.middleLandingDepth / 2) * s)
                    let b = CGPoint(x: lower.x, y: lower.y - (pair.1 == 1 ? Self.middleLandingDepth / 2 : 18) * s)
                    var shift: CGFloat = 0
                    for i in 0...48 {
                        let y = a.y - 7 * s + (b.y - a.y + 14 * s) * CGFloat(i) / 48
                        let t = min(1, max(0, (y - a.y) / (b.y - a.y)))
                        let center = a.x + (b.x - a.x) * t
                        let reach = 29 * s
                        shift = max(shift, reach - sign * (center - bankEdge(at: y)))
                    }
                    if shift > 0 {
                        if pair.0 == 0 { top.x += sign * shift } else { middle.x += sign * shift }
                        if pair.1 == 1 { middle.x += sign * shift } else { bottom.x += sign * shift }
                    }
                }
            }
            return District(id: index, right: right, upper: top, middle: middle, lower: bottom, scale: s)
        }
    }

    func crossings(for districts: [District]) -> [Crossing] {
        var result = districts.flatMap { court in
            [true, false].map { upper -> Crossing in
                let landing = upper ? court.upper : court.lower
                // Bridge railings end beside the landing, clear of the stair opening.
                let outer = CGPoint(x: landing.x - (court.right ? 1 : -1) * 30 * scale, y: landing.y)
                let water = waterPoint(at: outer.y, right: court.right)
                return Crossing(district: court.id, upper: upper, right: court.right, water: water,
                                inner: walkPoint(at: outer.y, right: court.right, outer: false),
                                entry: bankPoint(at: outer.y, right: court.right, offset: Self.innerHedgeOffset + Self.avenueHedgeWidth / 2, river: waterPoints(right: court.right)),
                                outer: outer, scale: scale,
                                riverSlope: (waterPoint(at: outer.y + 12, right: court.right).x - waterPoint(at: outer.y - 12, right: court.right).x) / 24)
            }
        }
        if let clock = landmarks.first {
            let outer = CGPoint(x: clock.point.x, y: clock.point.y + 34 * scale)
            let water = waterPoint(at: outer.y, right: true)
            result.append(Crossing(district: -1, upper: false, right: true, water: water,
                                   inner: walkPoint(at: outer.y, right: true, outer: false),
                                   entry: bankPoint(at: outer.y, right: true, offset: Self.innerHedgeOffset + Self.avenueHedgeWidth / 2, river: waterPoints(right: true)),
                                   outer: outer, scale: scale,
                                   riverSlope: (waterPoint(at: outer.y + 12, right: true).x - waterPoint(at: outer.y - 12, right: true).x) / 24))
        }
        return result
    }

    /// Offsets use distance to the shared river polyline, not a horizontal shift.
    private func bankPoint(at y: CGFloat, right: Bool, offset: CGFloat, river: [CGPoint]) -> CGPoint {
        let center = waterPoint(at: y, right: right), radius = abs(offset) * scale
        let direction: CGFloat = (right ? 1 : -1) * (offset >= 0 ? 1 : -1)
        let step = (river.last!.y - river[0].y) / CGFloat(river.count - 1)
        let first = max(0, Int(floor((y - radius - river[0].y) / step)) - 1)
        let last = min(river.count - 1, Int(ceil((y + radius - river[0].y) / step)) + 1)
        // SwiftUI can briefly propose an empty section while preparing the map.
        guard first < last else { return CGPoint(x: center.x + direction * radius, y: y) }
        func inside(_ x: CGFloat) -> Bool {
            for i in first..<last {
                let a = river[i], b = river[i + 1], dx = b.x - a.x, dy = b.y - a.y
                let t = max(0, min(1, ((x - a.x) * dx + (y - a.y) * dy) / (dx * dx + dy * dy)))
                let px = x - a.x - t * dx, py = y - a.y - t * dy
                if px * px + py * py <= radius * radius { return true }
            }
            return false
        }
        var inner = center.x
        var outer = inner + direction * max(scenery.width + 300, radius * 12)
        for _ in 0..<19 {
            let x = (inner + outer) / 2
            if inside(x) { inner = x } else { outer = x }
        }
        return CGPoint(x: (inner + outer) / 2, y: y)
    }

    func bankContour(right: Bool, offset: CGFloat, from start: CGFloat, to end: CGFloat) -> [CGPoint] {
        let river = waterPoints(right: right)
        let count = max(2, Int(ceil((end - start) / 3)))
        return (0...count).map { i in
            let y = start + (end - start) * CGFloat(i) / CGFloat(count)
            return bankPoint(at: y, right: right, offset: offset, river: river)
        }
    }

    func walkPoint(at y: CGFloat, right: Bool, outer: Bool) -> CGPoint {
        bankPoint(at: y, right: right, offset: outer ? Self.outerWalkOffset : Self.innerWalkOffset, river: waterPoints(right: right))
    }

    /// The hedge turns into each bridge's actual end posts. Its opening is
    /// measured at ground level, including the hedge's upward extrusion.
    func avenueHedges(right: Bool, crossings: [Crossing]) -> [[CGPoint]] {
        let s = scale, sign: CGFloat = right ? 1 : -1
        let height = Self.avenueHedgeHeight * s, shoulder: CGFloat = 22 * s
        let river = waterPoints(right: right)
        func foot(at y: CGFloat) -> CGPoint {
            let top = bankPoint(at: y, right: right, offset: Self.innerHedgeOffset, river: river)
            return CGPoint(x: top.x, y: top.y + height)
        }
        func bend(_ a: CGPoint, _ b: CGPoint, _ c: CGPoint, _ d: CGPoint) -> [CGPoint] {
            (0...16).map { i in
                let t = CGFloat(i) / 16, u = 1 - t
                return CGPoint(x: u*u*u*a.x + 3*u*u*t*b.x + 3*u*t*t*c.x + t*t*t*d.x,
                               y: u*u*u*a.y + 3*u*u*t*b.y + 3*u*t*t*c.y + t*t*t*d.y)
            }
        }
        var runs: [[CGPoint]] = [], lead: [CGPoint] = []
        var start = -scenery.routeOffset - 12
        for crossing in crossings.filter({ $0.right == right }).sorted(by: { $0.water.y < $1.water.y }) {
            let back = CGPoint(x: crossing.inner.x, y: crossing.water.y + Self.bridgeBackEdge * s)
            let front = CGPoint(x: crossing.inner.x, y: crossing.water.y + Self.bridgeFrontEdge * s)
            let end = back.y - shoulder - height
            if start < end {
                var points = lead + bankContour(right: right, offset: Self.innerHedgeOffset, from: start, to: end).map {
                    CGPoint(x: $0.x, y: $0.y + height)
                }
                let a = foot(at: end), previous = foot(at: end - 1)
                points += bend(a, .init(x: a.x + (a.x - previous.x) * shoulder * 0.6, y: a.y + shoulder * 0.6),
                               .init(x: back.x - sign * 8 * s, y: back.y), back).dropFirst()
                runs.append(points)
            }
            start = front.y + shoulder - height
            let d = foot(at: start), next = foot(at: start + 1)
            lead = bend(front, .init(x: front.x - sign * 8 * s, y: front.y),
                        .init(x: d.x - (next.x - d.x) * shoulder * 0.6, y: d.y - shoulder * 0.6), d)
        }
        let end = scenery.height - scenery.routeOffset + 12
        if start < end {
            runs.append(lead + bankContour(right: right, offset: Self.innerHedgeOffset, from: start, to: end).map {
                CGPoint(x: $0.x, y: $0.y + height)
            })
        }
        return runs
    }

    func waterPoints(right: Bool) -> [CGPoint] {
        let start = -scenery.routeOffset - 96, end = scenery.height - scenery.routeOffset + 96
        let count = Int(ceil((end - start) / 4))
        return (0...count).map { i in
            waterPoint(at: start + (end - start) * CGFloat(i) / CGFloat(count), right: right)
        }
    }

    func waterway(right: Bool) -> Path {
        Path { $0.addLines(waterPoints(right: right)) }
    }

    func waterPoint(at y: CGFloat, right: Bool) -> CGPoint {
        let sign: CGFloat = right ? 1 : -1
        let outside = right ? scenery.width + 120 * scale : -120 * scale
        func inner(_ row: CGFloat) -> CGFloat { scenery.centerX(at: row) + sign * 109 * scale }
        func curve(_ a: CGPoint, _ b: CGPoint, _ c: CGPoint, _ d: CGPoint) -> CGPoint {
            var low: CGFloat = 0, high: CGFloat = 1
            for _ in 0..<22 {
                let t = (low + high) / 2, u = 1 - t
                let row = u * u * u * a.y + 3 * u * u * t * b.y + 3 * u * t * t * c.y + t * t * t * d.y
                if row < y { low = t } else { high = t }
            }
            let t = (low + high) / 2, u = 1 - t
            return CGPoint(x: u * u * u * a.x + 3 * u * u * t * b.x + 3 * u * t * t * c.x + t * t * t * d.x, y: y)
        }
        // Horizontal mouths join the river with matching tangents. Bending a
        // moving x-offset inwards used to pinch the parallel paths into corners.
        let entryY: CGFloat = -140, joinedY: CGFloat = WorldRouteTrail.chapterFirstNodeY
        if y <= entryY { return CGPoint(x: outside, y: y) }
        if y < joinedY {
            let x = inner(joinedY)
            return curve(.init(x: outside, y: entryY), .init(x: x + sign * 95 * scale, y: entryY),
                         .init(x: x, y: joinedY - 105), .init(x: x, y: joinedY))
        }
        let exitY = scenery.height - scenery.routeOffset - 28
        let leavingY = min(1655, exitY - 180)
        if y <= leavingY { return CGPoint(x: inner(y), y: y) }
        if y < exitY {
            let x = inner(leavingY), slope = (inner(leavingY + 1) - inner(leavingY - 1)) / 2
            return curve(.init(x: x, y: leavingY), .init(x: x + slope * 70, y: leavingY + 70),
                         .init(x: x + sign * 100 * scale, y: exitY), .init(x: outside, y: exitY))
        }
        return CGPoint(x: outside, y: y)
    }
}

/// Only the visible water tiles tick. The stonework and its occlusion masks stay cached.
private final class CastleWaterPlan {
    private static let plans: NSCache<NSString, CastleWaterPlan> = {
        let cache = NSCache<NSString, CastleWaterPlan>(); cache.countLimit = 8; return cache
    }()
    static func cached(scenery: WorldSceneryLayout) -> CastleWaterPlan {
        let key = "\(scenery.width):\(scenery.height):\(scenery.routeOffset)" as NSString
        if let plan = plans.object(forKey: key) { return plan }
        let plan = CastleWaterPlan(scenery: scenery)
        plans.setObject(plan, forKey: key)
        return plan
    }
    struct Feature {
        let point: CGPoint
        let scale: CGFloat
        let depth: CGFloat
        let cascadeRight: Bool?
        var bounds: CGRect {
            if cascadeRight != nil {
                return CGRect(x: point.x - 100 * scale, y: point.y - 42 * scale, width: 200 * scale, height: 84 * scale)
            }
            return CGRect(x: point.x - 58 * scale, y: point.y - 118 * scale, width: 116 * scale, height: 144 * scale)
        }
    }
    let layout: CastleKingdomLayout
    let districts: [CastleKingdomLayout.District]
    let crossings: [CastleKingdomLayout.Crossing]
    let features: [Feature]
    let waterways: [Path]
    let walks: [[Path]]
    let hedges: [[[CGPoint]]]

    init(scenery: WorldSceneryLayout) {
        let layout = CastleKingdomLayout(scenery: scenery)
        let districts = layout.districts
        let crossings = layout.crossings(for: districts)
        self.layout = layout
        self.districts = districts
        self.crossings = crossings
        self.features = CastleKingdomLayout.cascades.map {
            Feature(point: layout.waterPoint(at: $0.y, right: $0.right), scale: layout.scale,
                    depth: $0.y + 24 * layout.scale, cascadeRight: $0.right)
        } + districts.flatMap { layout.fountains(for: $0) }.map {
            Feature(point: $0.point, scale: $0.scale, depth: $0.depth, cascadeRight: nil)
        }
        waterways = [false, true].map { layout.waterway(right: $0) }
        walks = [false, true].map { right in
            [false, true].map { outer in
                Path { $0.addLines(layout.bankContour(right: right,
                    offset: outer ? CastleKingdomLayout.outerWalkOffset : CastleKingdomLayout.innerWalkOffset,
                    from: -scenery.routeOffset - 16, to: scenery.height - scenery.routeOffset + 16)) }
            }
        }
        hedges = [false, true].map { layout.avenueHedges(right: $0, crossings: crossings) }
    }
}

private struct CastleWaterLife: View {
    let routeOffset: CGFloat
    let viewportHeight: CGFloat
    var fixedTime: TimeInterval? = nil
    var frozen = false

    var body: some View {
        GeometryReader { geometry in
            let plan = CastleWaterPlan.cached(scenery: WorldSceneryLayout(width: geometry.size.width, height: geometry.size.height, routeOffset: routeOffset))
            ZStack(alignment: .topLeading) {
                ForEach(0..<Int(ceil(geometry.size.height / 320)), id: \.self) { index in
                    let frame = CGRect(x: 0, y: CGFloat(index) * 320, width: geometry.size.width,
                                       height: min(320, geometry.size.height - CGFloat(index) * 320))
                    CastleWaterSurface(plan: plan, frame: frame, viewportHeight: viewportHeight, fixedTime: fixedTime, frozen: frozen)
                        .mask(CastleWaterOcclusion(plan: plan, frame: frame))
                        .modifier(MapAnimationVisibility(viewportHeight: viewportHeight, alwaysVisible: fixedTime != nil || frozen))
                        .frame(width: frame.width, height: frame.height).position(x: frame.midX, y: frame.midY)
                }
                ForEach(Array(plan.features.enumerated()), id: \.offset) { item in
                    let feature = item.element
                    let frame = feature.bounds.offsetBy(dx: 0, dy: routeOffset)
                    CastleWaterSurface(plan: plan, frame: frame, viewportHeight: viewportHeight, feature: feature, fixedTime: fixedTime, frozen: frozen)
                        .mask(CastleWaterOcclusion(plan: plan, frame: frame, cutoff: feature.depth))
                        .modifier(MapAnimationVisibility(viewportHeight: viewportHeight, alwaysVisible: fixedTime != nil || frozen))
                        .frame(width: frame.width, height: frame.height).position(x: frame.midX, y: frame.midY)
                }
            }
        }.clipped().allowsHitTesting(false).accessibilityHidden(true)
    }
}

private struct CastleWaterOcclusion: View {
    let plan: CastleWaterPlan
    let frame: CGRect
    var cutoff: CGFloat = -.infinity

    var body: some View {
        Canvas { context, size in
            context.fill(Path(CGRect(origin: .zero, size: size)), with: .color(.white))
            let layout = plan.layout
            var c = context
            c.translateBy(x: -frame.minX, y: layout.scenery.routeOffset - frame.minY)
            c.blendMode = .destinationOut
            let depth = WorldSceneryDepth(minimumDepth: cutoff)
            CastleWorldPainter(context: c, liveWater: true).appendScenery(layout: layout, districts: plan.districts, crossings: plan.crossings, depth: depth)
            depth.draw()
            if 1675 > cutoff {
                WorldBossPainter(context: c).draw(worldID: 10, at: .init(x: layout.scenery.width - 79 * layout.scale, y: 1675), size: layout.scale * 0.88)
            }
        }
    }
}

private struct CastleWaterSurface: View {
    let plan: CastleWaterPlan
    let frame: CGRect
    let viewportHeight: CGFloat
    var feature: CastleWaterPlan.Feature? = nil
    var fixedTime: TimeInterval? = nil
    var frozen = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.dinoMapAnimationEpoch) private var animationEpoch
    @State private var visible = false

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 20,
                                paused: fixedTime != nil || frozen || reduceMotion || !visible || scenePhase != .active)) { timeline in
            Canvas { context, _ in
                let time = frozen || reduceMotion ? 0 : (fixedTime ?? timeline.date.timeIntervalSince(animationEpoch ?? Date(timeIntervalSinceReferenceDate: 0)))
                var c = context
                c.translateBy(x: -frame.minX, y: plan.layout.scenery.routeOffset - frame.minY)
                if let feature {
                    if let right = feature.cascadeRight {
                        CastleWorldPainter(context: c, time: time).cascadeCurrent(layout: plan.layout, at: feature.point.y, right: right)
                    } else {
                        c.translateBy(x: feature.point.x, y: feature.point.y)
                        c.scaleBy(x: feature.scale, y: feature.scale)
                        CastleWorldPainter(context: c, time: time).fountainWater()
                    }
                } else {
                    let painter = CastleWorldPainter(context: c, time: time)
                    for right in [false, true] { painter.riverCurrent(layout: plan.layout, right: right) }
                }
            }
        }
        .readGeometry(for: Bool.self) { proxy in
            let rect = proxy.frame(in: .named("adventure.map.viewport"))
            return rect.maxY > -128 && rect.minY < viewportHeight + 128
        } action: { visible = $0 }
    }
}

/// The final chapter is a royal garden of blue roofs, pale stone and running water.
private struct CastleWorldPainter {
    let context: GraphicsContext
    var scenery: WorldSceneryLayout? = nil
    var depth: WorldSceneryDepth? = nil
    var depthOffset: CGFloat = 0
    var liveWater = false
    var time: TimeInterval = 0
    var rasterBounds: CGRect? = nil

    private func at(_ point: CGPoint, size: CGFloat = 1, mirror: Bool = false, radius: CGFloat = 0, rise: CGFloat = 0, draw: @escaping (CastleWorldPainter) -> Void) {
        let point = scenery?.position(point, radius: radius, rise: rise) ?? point
        var c = context; c.translateBy(x: point.x, y: point.y)
        c.scaleBy(x: mirror ? -size : size, y: size)
        if let depth {
            depth.add(at: depthOffset + point.y) { draw(.init(context: c, liveWater: liveWater, time: time)) }
        } else { draw(.init(context: c, liveWater: liveWater, time: time)) }
    }
    private func material(_ path: Path, _ colors: [UInt32]) {
        let r = path.boundingRect
        context.fill(path, with: .linearGradient(Gradient(colors: colors.map { Color(dinoHex: $0) }),
                                                startPoint: .init(x: r.minX, y: r.minY), endPoint: .init(x: r.maxX, y: r.maxY)))
    }
    private func polygon(_ points: [CGPoint], _ colors: [UInt32]) {
        var p = Path(); p.addLines(points); p.closeSubpath(); material(p, colors)
    }
    private func rounded(_ r: CGRect, _ radius: CGFloat, _ colors: [UInt32]) {
        material(Path(roundedRect: r, cornerRadius: radius), colors)
    }
    private func oval(_ r: CGRect, _ colors: [UInt32]) {
        context.fill(Path(ellipseIn: r), with: .radialGradient(Gradient(colors: colors.map { Color(dinoHex: $0) }),
                                                            center: .init(x: r.minX + r.width * 0.3, y: r.minY + r.height * 0.2),
                                                            startRadius: 0, endRadius: max(r.width, r.height)))
    }
    private func line(_ points: [CGPoint], _ color: UInt32, _ width: CGFloat, opacity: Double = 1) {
        var p = Path(); p.addLines(points)
        context.stroke(p, with: .color(Color(dinoHex: color).opacity(opacity)),
                       style: StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round))
    }
    private func glow(_ point: CGPoint, radius: CGFloat, color: UInt32, opacity: Double) {
        context.fill(Path(ellipseIn: CGRect(x: point.x - radius, y: point.y - radius, width: radius * 2, height: radius * 2)),
                     with: .radialGradient(Gradient(colors: [Color(dinoHex: color).opacity(opacity), Color(dinoHex: color).opacity(0)]),
                                           center: point, startRadius: 0, endRadius: radius))
    }


    /// The coast continues under the royal moats. Stone retaining walls,
    /// planted embankments and towers own their boundaries above this sand.
    private func harbourGround(in size: CGSize) {
        context.fill(Path(CGRect(origin: .zero, size: size)), with: .color(Color(dinoHex: 0xF6DBA3)))
    }

    func landscape(in size: CGSize, routeOffset: CGFloat, depth: WorldSceneryDepth) {
        let w = size.width, h = size.height, scale = min(1.30, max(0.82, size.width / 390))
        harbourGround(in: size)
        var c = context; c.translateBy(x: 0, y: routeOffset)
        let scenery = WorldSceneryLayout(width: w, height: h, routeOffset: routeOffset)
        let plan = CastleWaterPlan.cached(scenery: scenery)
        let layout = plan.layout
        let ground = CastleWorldPainter(context: c, liveWater: liveWater, time: time,
                                        rasterBounds: rasterBounds?.offsetBy(dx: 0, dy: -routeOffset))
        let districts = plan.districts
        let crossings = plan.crossings
        ground.royalGround(plan: plan)
        entrance(width: w, scale: scale)
        ground.appendScenery(layout: layout, districts: districts, crossings: crossings, depth: depth, offset: routeOffset)
        // Broad tablet gardens have their own connected outer gallery. On a
        // phone these spaces continue naturally beyond the edge of the map.
        if w > 650 {
            for right in [false, true] {
                for i in 0..<4 {
                    let y = 340 + CGFloat(i) * 350
                    let x: CGFloat = right ? w - 57 * scale : 57 * scale
                    let walk = layout.walkPoint(at: y, right: right, outer: true)
                    ground.pavedLink(from: CGPoint(x: x, y: y), to: walk, width: 13 * scale)
                    depth.add(at: routeOffset + y + 20 * scale) {
                        ground.at(CGPoint(x: x, y: y), size: scale * 0.84) { garden in
                            garden.terrace(width: 111)
                            if i % 2 == 0 { garden.tower(at: .zero, size: 0.80, time: nil) }
                            else { garden.dinoStatue(at: .zero, size: 0.82, mirror: right) }
                            garden.lantern(at: CGPoint(x: right ? -35 : 35, y: 10), size: 0.69)
                            garden.flowers(at: CGPoint(x: 26, y: 14), size: 0.75)
                        }
                    }
                }
            }
        }
    }

    func appendScenery(layout: CastleKingdomLayout, districts: [CastleKingdomLayout.District],
                       crossings: [CastleKingdomLayout.Crossing], depth: WorldSceneryDepth, offset: CGFloat = 0) {
        for cascade in CastleKingdomLayout.cascades {
            depth.add(at: offset + cascade.y + 24 * layout.scale) {
                self.cascade(layout: layout, at: cascade.y, right: cascade.right)
            }
        }
        for item in layout.landmarks {
            depth.add(at: offset + item.point.y + 28 * item.scale) { clockQuay(item, layout: layout) }
        }
        for district in districts {
            depth.add(at: offset + district.lower.y + 41 * layout.scale) { royalDistrict(district, layout: layout) }
        }
        for crossing in crossings {
            depth.add(at: offset + crossing.outer.y + 42 * layout.scale) { royalBridge(crossing) }
        }
    }

    private func entrance(width: CGFloat, scale: CGFloat) {
        // Ground and mist continue from the coast; there is no new sky band.
        var far = context; far.opacity = 0.34
        far.clipToLayer { mask in
            mask.fill(Path(CGRect(x: 0, y: 0, width: width, height: 270 * scale)),
                      with: .linearGradient(Gradient(stops: [.init(color: .clear, location: 0), .init(color: .white, location: 0.25), .init(color: .white, location: 0.62), .init(color: .clear, location: 1)]), startPoint: .zero, endPoint: .init(x: 0, y: 270 * scale)))
        }
        let distant = CastleWorldPainter(context: far)
        for i in 0..<5 {
            distant.at(CGPoint(x: width * CGFloat(i) / 4, y: CGFloat(191 + (i % 2) * 22) * scale), size: scale * 0.71) { p in
                p.retainingWall(width: 162, height: 62, arches: 3)
                p.palace(at: CGPoint(x: 0, y: -38), size: 0.74)
                p.cypress(at: CGPoint(x: -62, y: 1), size: 0.73)
                p.cypress(at: CGPoint(x: 57, y: 10), size: 0.56)
            }
        }
        tower(at: CGPoint(x: 17 * scale, y: 212 * scale), size: scale * 0.84, time: nil)
        tower(at: CGPoint(x: width - 19 * scale, y: 227 * scale), size: scale * 0.95, time: nil)
        planter(at: CGPoint(x: 21 * scale, y: 234 * scale), size: scale)
        planter(at: CGPoint(x: width - 17 * scale, y: 246 * scale), size: scale)
    }
    private func royalGround(plan: CastleWaterPlan) {
        let layout = plan.layout, crossings = plan.crossings
        let s = layout.scale, scenery = layout.scenery
        for (side, right) in [false, true].enumerated() {
            let sign: CGFloat = right ? 1 : -1
            // Broad planted banks connect the courts instead of leaving little
            // isolated circular platforms in an otherwise empty landscape.
            var garden = Path()
            let start = -scenery.routeOffset + 32
            let end = scenery.height - scenery.routeOffset - 25
            for i in 0...160 {
                let y = start + (end - start) * CGFloat(i) / 160
                let x = scenery.centerX(at: y) + sign * 139 * s
                if i == 0 { garden.move(to: .init(x: x, y: y)) }
                else { garden.addLine(to: .init(x: x, y: y)) }
            }
            garden.addLine(to: .init(x: right ? scenery.width + 1 : -1, y: end))
            garden.addLine(to: .init(x: right ? scenery.width + 1 : -1, y: start)); garden.closeSubpath()
            context.fill(garden, with: .linearGradient(Gradient(stops: [
                .init(color: .clear, location: 0),
                .init(color: Color(dinoHex: 0xA5BC89).opacity(0.24), location: 0.12),
                .init(color: Color(dinoHex: 0x83A579).opacity(0.44), location: 0.5),
                .init(color: Color(dinoHex: 0xC5CBA0).opacity(0.24), location: 0.87),
                .init(color: .clear, location: 1)
            ]), startPoint: .init(x: 0, y: start), endPoint: .init(x: 0, y: end)))
            let water = plan.waterways[side]
            for (width, color): (CGFloat, UInt32) in [(38, 0xA4AA8C), (33, 0xFFF0CC), (25, 0xB3CFBD), (19, 0x53B5C7)] {
                context.stroke(water, with: .color(Color(dinoHex: color)), style: StrokeStyle(lineWidth: width * s, lineCap: .round, lineJoin: .round))
            }
            if !liveWater { riverCurrent(layout: layout, right: right) }
            for (walkIndex, outer) in [false, true].enumerated() {
                let walk = plan.walks[side][walkIndex]
                context.stroke(walk, with: .color(Color(dinoHex: 0xA6AA8B).opacity(0.7)), style: StrokeStyle(lineWidth: (outer ? 19 : 12) * s, lineCap: .round))
                context.stroke(walk, with: .linearGradient(Gradient(colors: [Color(dinoHex: 0xF6E8C9), Color(dinoHex: 0xD5D0AF)]), startPoint: .zero, endPoint: CGPoint(x: 0, y: 1700)), style: StrokeStyle(lineWidth: (outer ? 15 : 8) * s, lineCap: .round))
            }
            for crossing in crossings where crossing.right == right && !crossing.upper {
                let start = CGPoint(x: scenery.centerX(at: crossing.inner.y) + sign * 23, y: crossing.inner.y)
                pavedLink(from: start, to: crossing.entry, width: 9 * s)
            }
            for crossing in crossings where crossing.right == right {
                bridgeApproach(crossing)
            }
            for (index, points) in plan.hedges[side].enumerated() {
                hedge(along: points, height: CastleKingdomLayout.avenueHedgeHeight * s,
                      width: CastleKingdomLayout.avenueHedgeWidth * s, roses: index % 2 == 0)
            }
        }
    }

    private func bridgeApproach(_ crossing: CastleKingdomLayout.Crossing) {
        at(crossing.water, size: crossing.scale) { p in
            let inner = (crossing.inner.x - crossing.water.x) / crossing.scale
            let entry = (crossing.entry.x - crossing.water.x) / crossing.scale
            let span = inner - entry
            let back = CastleKingdomLayout.bridgeBackEdge, front = CastleKingdomLayout.bridgeFrontEdge
            // A level, gently flared apron connects the avenue through the hedge
            // to the bridge deck. The hedge returns end at the same two newels.
            let floor = crossing.approachFloor
            p.context.stroke(floor, with: .color(Color(dinoHex: 0xB8B396)), style: StrokeStyle(lineWidth: 2, lineJoin: .round))
            p.context.fill(floor, with: .linearGradient(Gradient(colors: [Color(dinoHex: 0xFFF4D4), Color(dinoHex: 0xDED0AB)]),
                                                       startPoint: .init(x: entry, y: back - 6), endPoint: .init(x: inner, y: front + 6)))
            var paving = p.context; paving.clip(to: floor)
            let joints = CastleWorldPainter(context: paving)
            for t: CGFloat in [0.25, 0.55, 0.85] {
                let x = entry + span * t
                joints.line([.init(x: x, y: back - 6), .init(x: x + 2, y: front + 6)], 0xBEB599, 0.6)
            }
            joints.line([.init(x: entry, y: -1), .init(x: inner, y: -1)], 0xC8BDA0, 0.55)
        }
    }

    private func clockQuay(_ item: CastleKingdomLayout.Landmark, layout: CastleKingdomLayout) {
        at(item.point, size: layout.scale) { p in
            let outer = max(36, (layout.scenery.width - item.point.x) / layout.scale + 12)
            p.at(CGPoint(x: (outer - 34) / 2, y: 47)) { wall in
                wall.retainingWall(width: outer + 34, height: 29, arches: 2)
            }
            p.polygon([.init(x: -34, y: -28), .init(x: outer, y: -28), .init(x: outer + 2, y: 34), .init(x: -34, y: 34)], [0xFFF2D1, 0xDFD3B0])
            for y: CGFloat in [-12, 7, 25] { p.line([.init(x: -32, y: y), .init(x: outer - 2, y: y)], 0xC3B89B, 0.7) }
            p.tower(at: CGPoint(x: 0, y: -16), size: 1.03, time: .init(hour: 10, minute: 25))
            p.lantern(at: CGPoint(x: -26, y: 17), size: 0.52)
            p.planter(at: CGPoint(x: outer - 8, y: 25), size: 0.68)
            p.hedge(from: CGPoint(x: 30, y: -19), to: CGPoint(x: 30, y: 17), height: 12, width: 10, roses: true)
        }
    }

    private func pavedLink(from start: CGPoint, to end: CGPoint, width: CGFloat) {
        var path = Path(); path.move(to: start)
        path.addCurve(to: end, control1: CGPoint(x: start.x + (end.x - start.x) * 0.35, y: start.y),
                      control2: CGPoint(x: start.x + (end.x - start.x) * 0.70, y: end.y))
        context.stroke(path, with: .color(Color(dinoHex: 0xA6AA8C).opacity(0.65)), style: StrokeStyle(lineWidth: width + 4, lineCap: .round))
        context.stroke(path, with: .color(Color(dinoHex: 0xEAE1BF)), style: StrokeStyle(lineWidth: width, lineCap: .round))
        context.stroke(path, with: .color(Color(dinoHex: 0xFFF2D3).opacity(0.7)), style: StrokeStyle(lineWidth: 0.8, lineCap: .round, dash: [2, 6]))
    }

    private func hedge(from start: CGPoint, to end: CGPoint, height: CGFloat, width: CGFloat, roses: Bool = false) {
        hedge(along: [start, end], height: height, width: width, roses: roses)
    }

    private func hedge(along points: [CGPoint], height: CGFloat, width: CGFloat, roses: Bool = false) {
        guard let start = points.first, let end = points.last, points.count > 1 else { return }
        var stem = Path(); stem.addLines(points)
        if let rasterBounds, !rasterBounds.intersects(stem.boundingRect.insetBy(dx: -width - 8, dy: -height - width - 8)) { return }
        let style = StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round)
        context.stroke(stem.offsetBy(dx: 1.5, dy: 5), with: .color(Color(dinoHex: 0x667D54).opacity(0.23)), style: StrokeStyle(lineWidth: width + 5, lineCap: .round))
        // Extrude the trimmed hedge all the way down to the soil. Drawing only
        // the top and the foot leaves an unintended transparent slot between them.
        for layer in stride(from: CGFloat(0), through: height, by: 1.4) {
            context.stroke(stem.offsetBy(dx: 0, dy: -layer), with: .linearGradient(Gradient(colors: [Color(dinoHex: 0x578550), Color(dinoHex: 0x3F7349)]), startPoint: .init(x: start.x, y: start.y - height), endPoint: .init(x: end.x, y: end.y + width)), style: style)
        }
        let top = stem.offsetBy(dx: 0, dy: -height)
        context.stroke(top, with: .linearGradient(Gradient(colors: [Color(dinoHex: 0xB7D182), Color(dinoHex: 0x79A65F), Color(dinoHex: 0x4D854B)]), startPoint: start, endPoint: end), style: style)
        var foliage = context; foliage.clip(to: top.strokedPath(style))
        let leaves = CastleWorldPainter(context: foliage)
        var lengths: [CGFloat] = [0]
        for pair in zip(points, points.dropFirst()) {
            lengths.append(lengths.last! + hypot(pair.1.x - pair.0.x, pair.1.y - pair.0.y))
        }
        let length = lengths.last!, count = max(5, Int(length / max(2, width * 0.24)))
        var segment = 0
        for i in 0...count {
            let distance = length * CGFloat(i) / CGFloat(count)
            while segment < points.count - 2 && lengths[segment + 1] < distance { segment += 1 }
            let a = points[segment], b = points[segment + 1], span = max(0.01, lengths[segment + 1] - lengths[segment])
            let t = (distance - lengths[segment]) / span
            let normal = CGPoint(x: -(b.y - a.y) / span, y: (b.x - a.x) / span)
            let offset = CGFloat((i * 17) % 11 - 5) / 10 * width
            let x = a.x + (b.x - a.x) * t + normal.x * offset
            let y = a.y + (b.y - a.y) * t + normal.y * offset - height
            if let rasterBounds, !rasterBounds.insetBy(dx: -width, dy: -width).contains(CGPoint(x: x, y: y)) { continue }
            leaves.oval(CGRect(x: x - width * 0.12, y: y - width * 0.15, width: width * 0.29, height: width * 0.38),
                        i % 3 == 0 ? [0xD1DF9A, 0x99BF73, 0x699956] : [0xA4C57D, 0x77A766, 0x4C864F])
            if roses && i % 8 == 2 {
                leaves.oval(CGRect(x: x - width * 0.17, y: y - width * 0.14, width: width * 0.36, height: width * 0.32), [0xFFE2EC, 0xEF91B2, 0xCD5C91])
            }
        }
        context.stroke(top.offsetBy(dx: -width * 0.12, dy: -width * 0.18), with: .color(Color(dinoHex: 0xD6E5A6).opacity(0.33)), style: StrokeStyle(lineWidth: 0.7, lineCap: .round))
    }

    private func landing(at point: CGPoint, width: CGFloat, depth: CGFloat, right: Bool, exit: Bool = false, terminal: Bool = false,
                         arrival: CGFloat = 0, departure: CGFloat = 0) {
        at(point) { p in
            let half = width / 2, back = -depth / 2, front = depth / 2
            let floor = Path(roundedRect: CGRect(x: -half, y: back, width: width, height: depth), cornerRadius: 3)
            // The slab stays close to the stair cheeks, with rounded corners
            // rather than the previous flared, pointed balcony and zigzag rail.
            p.context.fill(floor.offsetBy(dx: 0, dy: 2.5), with: .color(Color(dinoHex: 0xB6B69A)))
            p.rounded(CGRect(x: -half, y: back, width: width, height: depth), 3, [0xFFF5D9, 0xE9DEBF])
            var paving = p.context; paving.clip(to: floor)
            let joints = CastleWorldPainter(context: paving)
            for x in stride(from: -half + 12, through: half - 6, by: 15) {
                joints.line([.init(x: x, y: back + 1), .init(x: x, y: front - 1)], 0xC6BDA2, 0.55, opacity: 0.7)
            }
            for t: CGFloat in [0.33, 0.67] {
                let y = back + depth * t
                joints.line([.init(x: -half + 1, y: y), .init(x: half - 1, y: y)], 0xC9BFA3, 0.6, opacity: 0.7)
            }
            var lip = Path(); lip.move(to: .init(x: -half, y: front - 3))
            lip.addQuadCurve(to: .init(x: -half + 3, y: front), control: .init(x: -half, y: front))
            lip.addLine(to: .init(x: half - 3, y: front))
            lip.addQuadCurve(to: .init(x: half, y: front - 3), control: .init(x: half, y: front))
            p.context.stroke(lip, with: .color(Color(dinoHex: 0xFFFAE4)), style: StrokeStyle(lineWidth: 1.3, lineCap: .round))
            if terminal {
                for x in stride(from: -half + 5, through: half - 4, by: 9) {
                    p.rounded(CGRect(x: x - 1.7, y: front - 21, width: 3.4, height: 20), 1.4, [0xFFF1D1, 0xB9B497])
                }
                p.line([.init(x: -half + 3, y: front - 23), .init(x: half - 3, y: front - 23)], 0xFFF2D0, 3.4)
            }
            if !exit {
                let sign: CGFloat = right ? -1 : 1
                let rail = (0...16).map { i -> CGPoint in
                    let t = CGFloat(i) / 16, u = 1 - t
                    return CGPoint(x: sign * 25 + 3*u*u*t*arrival*8 - 3*u*t*t*departure*8,
                                   y: back + depth * t)
                }
                for i in [0, 8, 16] {
                    let e = rail[i]
                    p.rounded(CGRect(x: e.x - 1.8, y: e.y - 22, width: 3.6, height: 21), 1.4, [0xFFF1D1, 0xB9B497])
                }
                p.line(rail.map { .init(x: $0.x, y: $0.y - 23) }, 0xA8A88E, 5.6)
                p.line(rail.map { .init(x: $0.x, y: $0.y - 25) }, 0xFFF2D0, 3.4)
            }
        }
    }

    private func royalDistrict(_ district: CastleKingdomLayout.District, layout: CastleKingdomLayout) {
        let s = district.scale, sign: CGFloat = district.right ? 1 : -1
        at(district.upper, size: s) { p in
            func local(_ point: CGPoint) -> CGPoint {
                CGPoint(x: (point.x - district.upper.x) / s, y: (point.y - district.upper.y) / s)
            }
            let mid = local(district.middle), low = local(district.lower)
            let outside = district.right ? (layout.scenery.width - district.upper.x) / s + 12 : district.upper.x / s + 12
            let a = min(-sign * 33, sign * max(64, outside)), b = max(-sign * 33, sign * max(64, outside))
            // The upper forecourt and first flight share a clear, level landing.
            p.at(CGPoint(x: (a + b) / 2, y: 28)) { wall in
                wall.retainingWall(width: b - a, height: 28, arches: max(2, Int((b - a) / 32)))
            }
            p.polygon([.init(x: a, y: -74), .init(x: b, y: -74), .init(x: b + 2, y: 18), .init(x: a - 2, y: 18)], [0xF4E9CA, 0xDCD2AE])
            for y: CGFloat in [-57, -39, -21] { p.line([.init(x: a + 2, y: y), .init(x: b - 2, y: y)], 0xBFB99A, 0.65, opacity: 0.7) }
            for x in stride(from: a + 12, through: b - 8, by: 19) {
                p.line([.init(x: x, y: -72), .init(x: x + 2, y: -7)], 0xC4BA9A, 0.7, opacity: 0.65)
            }
            if district.id == 2 || district.id == 3 {
                let opening: CGFloat = district.id == 3 ? 0 : sign * 65
                if opening - 25 > a + 5 {
                    p.hedge(from: .init(x: a + 5, y: -66), to: .init(x: min(b - 5, opening - 25), y: -66), height: 14, width: 12, roses: true)
                }
                if opening + 25 < b - 5 {
                    p.hedge(from: .init(x: max(a + 5, opening + 25), y: -66), to: .init(x: b - 5, y: -66), height: 14, width: 12, roses: true)
                }
            } else {
                p.hedge(from: .init(x: a + 5, y: -66), to: .init(x: b - 5, y: -66), height: 14, width: 12, roses: true)
            }
            if district.id == 3 {
                // Past the open crown gate the paving turns into the upper
                // courtyard, before reaching its rear hedge boundary.
                p.pavedLink(from: CGPoint(x: 0, y: -7), to: CGPoint(x: sign * 60, y: -45), width: 18)
            }
            if district.id == 0 {
                p.dinoStatue(at: CGPoint(x: sign * 12, y: -56), size: 0.82, mirror: district.right)
                p.cypress(at: CGPoint(x: sign * 61, y: -27), size: 0.80)
            } else if district.id == 1 {
                p.palace(at: CGPoint(x: sign * 33, y: -39), size: 0.77)
            } else if district.id == 2 {
                p.gardenGate(at: CGPoint(x: sign * 65, y: -29), size: 0.72, iron: true)
            } else {
                p.gardenGate(at: CGPoint(x: 0, y: -22), size: 1.04, iron: false)
                p.tower(at: CGPoint(x: sign * 78, y: -18), size: 0.64, time: nil)
            }
            // A clear forecourt runs straight onto the first tread. The short
            // decorative steps previously overlapped the bridge and its end posts.
            p.landing(at: .zero, width: 64, depth: 36, right: district.right, exit: true)
            // A side garden is reached from the intermediate balcony. Both
            // hedge borders stop at this opening and its gate has an open arch.
            let gardenWidth = district.right ? (layout.scenery.width - district.middle.x) / s - 47 : district.middle.x / s - 47
            if gardenWidth > 21 {
                let gardenCenter = CGPoint(x: mid.x + sign * (47 + gardenWidth / 2), y: mid.y - 5)
                p.parterre(at: gardenCenter, width: gardenWidth, height: 71, right: district.right, variation: district.id)
                p.pavedLink(from: mid, to: CGPoint(x: gardenCenter.x, y: mid.y), width: 12)
            }
            p.stairFlight(from: local(district.flights[0].top), to: local(district.flights[0].bottom), variation: district.id)
            let first = district.flights[0], second = district.flights[1]
            p.landing(at: mid, width: CastleKingdomLayout.middleLandingWidth, depth: CastleKingdomLayout.middleLandingDepth, right: district.right,
                      arrival: (first.bottom.x - first.top.x) / (first.bottom.y - first.top.y),
                      departure: (second.bottom.x - second.top.x) / (second.bottom.y - second.top.y))
            p.stairFlight(from: local(district.flights[1].top), to: local(district.flights[1].bottom), variation: district.id + 1)
            p.landing(at: low, width: 64, depth: 36, right: district.right, exit: true, terminal: true)
            if gardenWidth > 21 {
                p.gardenGate(at: CGPoint(x: mid.x + sign * 47, y: mid.y + 2), size: 0.48, iron: true)
            }
            p.lantern(at: CGPoint(x: mid.x - sign * 25, y: mid.y - 1), size: 0.36)
            p.lantern(at: CGPoint(x: low.x + sign * 30, y: low.y - 9), size: 0.45)
            p.planter(at: CGPoint(x: sign * 57, y: -20), size: 0.48)
            p.flowers(at: CGPoint(x: low.x + sign * 47, y: low.y + 9), size: 0.42)
            for fountain in layout.fountains(for: district) {
                p.fountain(at: local(fountain.point), size: fountain.scale / s)
            }
        }
    }

    private func stairFlight(from top: CGPoint, to bottom: CGPoint, variation: Int) {
        let flight = CastleKingdomLayout.Flight(top: top, bottom: bottom, scale: 1)
        for side: CGFloat in [-1, 1] {
            let a = flight.edge(0, side: side), b = flight.edge(1, side: side)
            polygon([.init(x: a.x + side * 6, y: a.y - 5), .init(x: b.x + side * 7, y: b.y - 4),
                     .init(x: b.x + side * 7, y: b.y + 9), .init(x: a.x + side * 6, y: a.y + 9)], [0xE6D9B8, 0xAAAe94, 0x909F88])
            for i in 0..<5 {
                let t = CGFloat(i) / 4, e = flight.edge(t, side: side)
                line([.init(x: e.x + side * 3, y: e.y + 6), .init(x: e.x + side * 7, y: e.y + 7)], 0xFFF0CB, 0.8, opacity: 0.7)
            }
        }
        for i in 0..<flight.steps {
            let t = CGFloat(i) / CGFloat(flight.steps), next = CGFloat(i + 1) / CGFloat(flight.steps)
            let a = flight.edge(t, side: -1), b = flight.edge(t, side: 1)
            let c = flight.edge(next, side: 1), d = flight.edge(next, side: -1)
            polygon([a, b, .init(x: c.x, y: c.y - 3.3), .init(x: d.x, y: d.y - 3.3)], [0xFFF2D4, 0xDED3B6, 0xC7C2A6])
            polygon([.init(x: d.x, y: d.y - 3.3), .init(x: c.x, y: c.y - 3.3), c, d], [0xB7B69E, 0x929F8C])
            line([.init(x: d.x, y: d.y - 3.3), .init(x: c.x, y: c.y - 3.3)], 0xFFFAE1, 1.4)
            if i % 3 == 1 { line([.init(x: (c.x + d.x) / 2, y: d.y - 7), .init(x: (c.x + d.x) / 2 + 1, y: d.y - 4)], 0xB8AF94, 0.65) }
        }
        for side: CGFloat in [-1, 1] {
            for i in 0...6 {
                let e = flight.edge(CGFloat(i) / 6, side: side)
                rounded(CGRect(x: e.x + side * 3 - 2, y: e.y - 22, width: 4, height: 19), 1.8, [0xFFF1D1, 0xB9B497])
                oval(CGRect(x: e.x + side * 3 - 3.3, y: e.y - 17, width: 6.6, height: 6), [0xF7E9C8, 0xB2AB8E])
            }
            let a = flight.edge(0, side: side), b = flight.edge(1, side: side)
            line([.init(x: a.x + side * 3, y: a.y - 23), .init(x: b.x + side * 3, y: b.y - 23)], 0xA8A88E, 5.6)
            line([.init(x: a.x + side * 3, y: a.y - 25), .init(x: b.x + side * 3, y: b.y - 25)], 0xFFF2D0, 3.4)
            let e = flight.edge(0.53, side: side)
            masonry(CGRect(x: e.x + side * 3 - 4, y: e.y - 27, width: 8, height: 26))
            rounded(CGRect(x: e.x + side * 3 - 6, y: e.y - 29, width: 12, height: 4), 1, [0xFFF2CD, 0xBAAA82])
            banner(at: CGPoint(x: e.x + side * 3, y: e.y - 2), size: 0.31)
        }
    }

    private func parterre(at point: CGPoint, width: CGFloat, height: CGFloat, right: Bool, variation: Int) {
        at(point) { p in
            let a = -width / 2, b = width / 2, back = -height * 0.72, front = height * 0.28
            p.rounded(CGRect(x: a - 3, y: back - 3, width: width + 6, height: height + 6), 7, [0xE9DCB8, 0xBCBF98])
            p.rounded(CGRect(x: a + 4, y: back + 4, width: width - 8, height: height - 8), 6, [0x86AB70, 0xA8BD86, 0x648E64])
            p.hedge(from: .init(x: a + 2, y: back), to: .init(x: b - 2, y: back), height: 11, width: 10, roses: true)
            let inner = right ? a : b, outer = right ? b : a
            let entryY: CGFloat = 5
            p.hedge(from: .init(x: outer, y: back), to: .init(x: outer, y: front), height: 10, width: 9)
            p.hedge(from: .init(x: inner, y: back), to: .init(x: inner, y: entryY - 13), height: 10, width: 9)
            if front > entryY + 13 { p.hedge(from: .init(x: inner, y: entryY + 13), to: .init(x: inner, y: front), height: 10, width: 9) }
            p.hedge(from: .init(x: a, y: front), to: .init(x: b, y: front), height: 10, width: 9, roses: true)
            p.pavedLink(from: .init(x: inner + (right ? -4 : 4), y: entryY), to: .init(x: 0, y: entryY), width: 10)
            p.pavedLink(from: .init(x: 0, y: entryY), to: .init(x: 0, y: back + 11), width: 9)
            if width > 70 {
                for side: CGFloat in [-1, 1] {
                    let x = side * width * 0.25
                    let ring = Path(ellipseIn: CGRect(x: x - width * 0.16, y: back + 17, width: width * 0.32, height: 27))
                    p.context.stroke(ring.offsetBy(dx: 0, dy: 3), with: .color(Color(dinoHex: 0x356F4B)), lineWidth: 8)
                    p.context.stroke(ring, with: .linearGradient(Gradient(colors: [Color(dinoHex: 0xAFCB7F), Color(dinoHex: 0x5A9854)]), startPoint: .init(x: x, y: back), endPoint: .init(x: x, y: front)), lineWidth: 7)
                    p.flowers(at: CGPoint(x: x, y: back + 31), size: min(0.64, width / 220))
                }
            } else { p.planter(at: CGPoint(x: 0, y: back + 27), size: 0.45) }
            if width > 110 {
                p.bench(at: CGPoint(x: (right ? 1 : -1) * width * 0.29, y: front - 3), size: 0.71)
                p.cypress(at: CGPoint(x: -width / 2 + 17, y: back + 1), size: 0.65)
                p.cypress(at: CGPoint(x: width / 2 - 17, y: back + 1), size: 0.65)
            }
        }
    }

    private func bench(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            for x: CGFloat in [-16, 16] { p.rounded(CGRect(x: x - 2, y: -2, width: 4, height: 12), 1, [0xE8D5A5, 0xA59169]) }
            p.rounded(CGRect(x: -24, y: -4, width: 48, height: 7), 2, [0xFFF1CE, 0xC7B58D])
            for y: CGFloat in [-20, -14] { p.rounded(CGRect(x: -22, y: y, width: 44, height: 4), 1.2, [0xA6C1C3, 0x567F85]) }
            for x: CGFloat in [-20, 20] { p.line([.init(x: x, y: -23), .init(x: x, y: 0)], 0xB99D65, 2) }
            p.crown(at: CGPoint(x: 0, y: -17), size: 0.29)
        }
    }

    private func gardenGate(at point: CGPoint, size: CGFloat, iron: Bool) {
        at(point, size: size) { p in
            // A real opening, including the paving behind the arch. No stone
            // fill or closed door covers the entrance to the upper courtyard.
            p.rounded(CGRect(x: -24, y: -8, width: 48, height: 15), 2, [0xE9DEB9, 0xC2C0A1])
            for side: CGFloat in [-1, 1] {
                p.masonry(CGRect(x: side * 31 - 8, y: -77, width: 16, height: 81))
                p.rounded(CGRect(x: side * 31 - 11, y: -81, width: 22, height: 7), 2, [0xFFF3D2, 0xC9B58D])
                if iron {
                    p.oval(CGRect(x: side * 31 - 5, y: -93, width: 10, height: 12), [0xFFE6A7, 0xC7A060])
                } else {
                    p.roof(at: CGPoint(x: side * 31, y: -84), size: 0.39)
                    p.banner(at: CGPoint(x: side * 31, y: -29), size: 0.48)
                }
            }
            var arch = Path(); arch.move(to: .init(x: -31, y: -73))
            arch.addCurve(to: .init(x: 31, y: -73), control1: .init(x: -27, y: -114), control2: .init(x: 27, y: -114))
            p.context.stroke(arch, with: .color(Color(dinoHex: iron ? 0x4F7D80 : 0xC5B590)), style: StrokeStyle(lineWidth: iron ? 4 : 14, lineCap: .round))
            p.context.stroke(arch.offsetBy(dx: 0, dy: -2), with: .color(Color(dinoHex: 0xFFE6AB)), lineWidth: iron ? 1.3 : 3)
            p.crown(at: CGPoint(x: 0, y: -103), size: iron ? 0.8 : 1.15)
            // Both wrought-iron leaves swing away to the sides of the route.
            for side: CGFloat in [-1, 1] {
                let hinge: CGFloat = side * 24
                for i in 0..<4 {
                    let x = hinge + side * CGFloat(i) * 3.3
                    p.line([.init(x: x, y: -62 + CGFloat(i) * 3), .init(x: x, y: 0)], 0x345F6D, 1.4)
                    p.oval(CGRect(x: x - 1.4, y: -65 + CGFloat(i) * 3, width: 2.8, height: 4), [0xFFEAAD, 0xBB965C])
                }
                p.line([.init(x: hinge, y: -51), .init(x: hinge + side * 10, y: -43)], 0xCBA966, 1.7)
                p.line([.init(x: hinge, y: -17), .init(x: hinge + side * 10, y: -14)], 0xCBA966, 1.7)
            }
            if !iron { p.ivy(at: CGPoint(x: -36, y: -72), size: 0.7) }
        }
    }

    private func royalBridge(_ crossing: CastleKingdomLayout.Crossing) {
        at(crossing.water, size: crossing.scale) { p in
            let inner = (crossing.inner.x - crossing.water.x) / crossing.scale
            let outer = (crossing.outer.x - crossing.water.x) / crossing.scale
            let left = min(inner, outer), right = max(inner, outer)
            let backEdge = CastleKingdomLayout.bridgeBackEdge, frontEdge = CastleKingdomLayout.bridgeFrontEdge
            let slope = crossing.riverSlope
            let skew = CGAffineTransform(a: 1, b: 0, c: slope, d: 1, tx: 0, ty: 0)
            var wall = Path(roundedRect: CGRect(x: left - 4, y: -5, width: right - left + 8, height: 43), cornerRadius: 3)
            let opening = Path(roundedRect: CGRect(x: -23, y: 8, width: 46, height: 60), cornerRadius: 23).applying(skew)
            wall.addPath(opening)
            var face = p.context
            face.clip(to: Path(CGRect(x: left - 4, y: -5, width: right - left + 8, height: 43)))
            face.fill(wall, with: .linearGradient(Gradient(colors: [Color(dinoHex: 0xFFF0CC), Color(dinoHex: 0xD5C6A3), Color(dinoHex: 0xA9B29A)]), startPoint: .init(x: left, y: -5), endPoint: .init(x: right, y: 38)), style: FillStyle(eoFill: true))
            for i in 0..<11 {
                let a = Double(i) * .pi / 11 + .pi, b = Double(i + 1) * .pi / 11 + .pi
                func voussoir(_ angle: Double, _ radius: CGFloat) -> CGPoint {
                    let y = 31 + CGFloat(sin(angle)) * radius
                    return CGPoint(x: CGFloat(cos(angle)) * radius + slope * y, y: y)
                }
                p.polygon([voussoir(a, 29), voussoir(b, 29), voussoir(b, 23), voussoir(a, 23)], i % 3 == 0 ? [0xFFF7DC, 0xD2BD94] : [0xF3E5C2, 0xC5B18D])
                p.line([voussoir(a, 23.5), voussoir(a, 28.5)], 0xA9A68B, 0.6)
            }
            // Back balustrade, stone deck, then front balustrade: the walkway
            // stays open from the inner promenade to the shared outer landing.
            for front in [false, true] {
                if front {
                    p.polygon([.init(x: left - 5, y: backEdge), .init(x: right + 5, y: backEdge), .init(x: right + 5, y: frontEdge), .init(x: left - 5, y: frontEdge)], [0xFFF4D4, 0xDED0AB])
                    for x in stride(from: left + 7, through: right - 3, by: 12) {
                        p.line([.init(x: x, y: -12), .init(x: x + 4, y: 10)], 0xBEB599, 0.65)
                    }
                    p.line([.init(x: left - 4, y: 11), .init(x: right + 4, y: 11)], 0xFFF8DB, 1.8)
                }
                let y = front ? frontEdge - 2 : backEdge
                for x in stride(from: left + 4, through: right - 3, by: 10) {
                    p.rounded(CGRect(x: x - 1.8, y: y - 21, width: 3.6, height: 20), 1.5, [0xFFF2D0, 0xBFB393])
                    p.oval(CGRect(x: x - 2.8, y: y - 16, width: 5.6, height: 6), [0xF3E7C4, 0xB8B095])
                }
                p.line([.init(x: left, y: y - 22), .init(x: right, y: y - 22)], 0xB3AA8B, 5)
                p.line([.init(x: left, y: y - 24), .init(x: right, y: y - 24)], 0xFFF0CA, 2.8)
                for x: CGFloat in [left, right] {
                    p.masonry(CGRect(x: x - 4, y: y - 28, width: 8, height: 28))
                    p.rounded(CGRect(x: x - 6, y: y - 31, width: 12, height: 5), 1, [0xFFF2CF, 0xBEA579])
                    p.oval(CGRect(x: x - 3, y: y - 38, width: 6, height: 8), [0xFFEAAF, 0xC6A267])
                }
            }
            for x: CGFloat in [left + 10, right - 10] { p.banner(at: CGPoint(x: x, y: 18), size: 0.29) }
            p.lantern(at: CGPoint(x: outer, y: -33), size: 0.30)
        }
    }

    private func cascade(layout: CastleKingdomLayout, at y: CGFloat, right: Bool) {
        let s = layout.scale, middle = layout.waterPoint(at: y, right: right)
        let channel = layout.waterway(right: right)
        // The masonry ends at the banks. No cap or oblique stroke crosses the water.
        var stone = context
        stone.clip(to: channel.strokedPath(StrokeStyle(lineWidth: 33 * s, lineCap: .round, lineJoin: .round)), options: .inverse)
        CastleWorldPainter(context: stone).at(middle, size: s) { p in
            p.retainingWall(width: 58, height: 33, arches: 2)
            p.ivy(at: CGPoint(x: right ? 28 : -28, y: -30), size: 0.40)
        }
        var water = context
        water.clip(to: channel.strokedPath(StrokeStyle(lineWidth: 19 * s, lineCap: .round, lineJoin: .round)))
        var curtain = Path()
        for i in 0...48 {
            let point = layout.waterPoint(at: y + (-42 + CGFloat(i) * 1.6) * s, right: right)
            if i == 0 { curtain.move(to: point) } else { curtain.addLine(to: point) }
        }
        water.stroke(curtain, with: .linearGradient(Gradient(stops: [
            .init(color: Color(dinoHex: 0xA3E6DF).opacity(0), location: 0),
            .init(color: Color(dinoHex: 0xA3E6DF).opacity(0.58), location: 0.22),
            .init(color: Color(dinoHex: 0x439DBD).opacity(0.65), location: 0.50),
            .init(color: Color(dinoHex: 0x73CECE).opacity(0.45), location: 0.77),
            .init(color: Color(dinoHex: 0x73CECE).opacity(0), location: 1)
        ]), startPoint: .init(x: middle.x, y: y - 42 * s), endPoint: .init(x: middle.x, y: y + 35 * s)),
                     style: StrokeStyle(lineWidth: 19 * s, lineCap: .round, lineJoin: .round))
        if !liveWater { cascadeCurrent(layout: layout, at: y, right: right) }
    }

    func riverCurrent(layout: CastleKingdomLayout, right: Bool) {
        let s = layout.scale
        var c = context
        c.clip(to: layout.waterway(right: right).strokedPath(StrokeStyle(lineWidth: 18 * s, lineCap: .round, lineJoin: .round)))
        let begin = -layout.scenery.routeOffset, end = layout.scenery.height - layout.scenery.routeOffset
        for lane in [-1, 1] {
            var stream = Path()
            for i in 0...220 {
                let y = begin + (end - begin) * CGFloat(i) / 220
                let center = layout.waterPoint(at: y, right: right)
                let sway = sin(y / 34 + CGFloat(lane) * 2.1) * 1.3 * s
                let point = CGPoint(x: center.x + CGFloat(lane) * 5.2 * s + sway, y: y)
                if i == 0 { stream.move(to: point) } else { stream.addLine(to: point) }
            }
            c.stroke(stream, with: .color(Color(dinoHex: 0xB8F1E5).opacity(0.46)),
                     style: StrokeStyle(lineWidth: 0.75 * s, lineCap: .round,
                                        dash: [8 * s, (28 + CGFloat(lane + 1) * 7) * s], dashPhase: -CGFloat(time * 15) * s))
        }
        let travel = CGFloat((time * 13).truncatingRemainder(dividingBy: 37))
        for i in 0..<Int((end - begin) / 37) + 1 {
            let y = begin + CGFloat(i) * 37 + travel
            let center = layout.waterPoint(at: y, right: right)
            let slope = (layout.waterPoint(at: y + 1, right: right).x - layout.waterPoint(at: y - 1, right: right).x) / 2
            let length = hypot(slope, 1), nx = 1 / length, ny = -slope / length
            let radius = CGFloat(3 + i % 3) * s
            var ripple = Path()
            ripple.move(to: .init(x: center.x - nx * radius, y: y - ny * radius))
            ripple.addQuadCurve(to: .init(x: center.x + nx * radius, y: y + ny * radius),
                                control: .init(x: center.x + slope / length * 2 * s, y: y + 2 / length * s))
            c.stroke(ripple, with: .color(Color(dinoHex: 0xECFFF6).opacity(0.65)), style: StrokeStyle(lineWidth: 0.85 * s, lineCap: .round))
        }
    }

    func cascadeCurrent(layout: CastleKingdomLayout, at y: CGFloat, right: Bool) {
        let s = layout.scale
        var c = context
        c.clip(to: layout.waterway(right: right).strokedPath(StrokeStyle(lineWidth: 18 * s, lineCap: .round, lineJoin: .round)))
        for lane in -2...2 {
            var thread = Path()
            for i in 0...40 {
                let row = y + (-37 + CGFloat(i) * 1.55) * s
                let center = layout.waterPoint(at: row, right: right)
                let slope = (layout.waterPoint(at: row + 1, right: right).x - layout.waterPoint(at: row - 1, right: right).x) / 2
                let length = hypot(slope, 1), across = CGFloat(lane) * 3.2 * s
                let point = CGPoint(x: center.x + across / length, y: row - across * slope / length)
                if i == 0 { thread.move(to: point) } else { thread.addLine(to: point) }
            }
            // Independently travelling, tapered ribbons avoid a common diagonal
            // cut across the top or foot of the cascade.
            for packet in 0..<3 {
                let phase = CGFloat((time * 0.95 + Double(lane + 2) * 0.137 + Double(packet) / 3).truncatingRemainder(dividingBy: 1))
                let start = max(0, phase - 0.21)
                let opacity = Double(sin(.pi * phase)) * (lane % 2 == 0 ? 0.85 : 0.48)
                c.stroke(thread.trimmedPath(from: start, to: phase), with: .color(Color(dinoHex: 0xF1FFF8).opacity(opacity)),
                         style: StrokeStyle(lineWidth: (lane % 2 == 0 ? 1.35 : 0.7) * s, lineCap: .round))
            }
        }
        for i in 0..<12 {
            let phase = (time * 0.85 + Double(i) / 12).truncatingRemainder(dividingBy: 1)
            let row = y + (14 + CGFloat(phase) * 23) * s
            let center = layout.waterPoint(at: row, right: right)
            let x = center.x + CGFloat((i * 7) % 13 - 6) * s
            let radius = (1.1 + CGFloat(phase) * 1.2) * s
            c.fill(Path(ellipseIn: CGRect(x: x - radius, y: row, width: radius * 2, height: radius)),
                   with: .color(Color(dinoHex: 0xF2FFF6).opacity((1 - phase) * 0.85)))
        }
    }

    private func retainingWall(width: CGFloat, height: CGFloat, arches: Int) {
        masonry(CGRect(x: -width / 2, y: -height, width: width, height: height + 8))
        for i in 0..<arches {
            let step = width / CGFloat(arches), x = -width / 2 + step * (CGFloat(i) + 0.5)
            let archWidth = min(24, step - 12)
            guard archWidth > 5 else { continue }
            let rect = CGRect(x: x - archWidth / 2, y: -height + 12, width: archWidth, height: height - 11)
            rounded(rect.insetBy(dx: -2, dy: -2), archWidth / 2 + 2, [0xFFF0CF, 0xCFBC94])
            rounded(rect, archWidth / 2, [0x8A9B8A, 0xB2BBA0, 0xC5C7A7])
            line([.init(x: rect.minX + 2, y: rect.maxY - 2), .init(x: rect.maxX - 2, y: rect.maxY - 2)], 0xDCD5AE, 2)
        }
        rounded(CGRect(x: -width / 2 - 3, y: -height - 4, width: width + 6, height: 8), 2, [0xFFF5D9, 0xC6BB97])
        line([.init(x: -width / 2, y: -height - 4), .init(x: width / 2, y: -height - 4)], 0xFFFFE5, 1.2)
        for i in 0..<max(1, Int(width / 25)) {
            let x = -width / 2 + 12 + CGFloat(i) * 25
            line([.init(x: x, y: -height - 3), .init(x: x + 2, y: -height + 3)], 0xAFA88A, 0.7, opacity: 0.7)
        }
    }

    private func court(kind: CastleKingdomLayout.Kind, right: Bool, variation: Int, outerExtent: CGFloat) {
        let width: CGFloat = kind == .palace || kind == .gate ? 170 : 128
        let left = right ? -width / 2 : -max(width / 2, outerExtent)
        let edge = right ? max(width / 2, outerExtent) : width / 2
        rounded(CGRect(x: left - 3, y: 9, width: edge - left + 6, height: 14), 5, [0xAAB491, 0xC3C59E, 0xCDD1AB])
        at(CGPoint(x: (left + edge) / 2, y: 0)) { p in
            p.retainingWall(width: edge - left, height: 23, arches: max(3, Int((edge - left) / 36)))
        }
        polygon([.init(x: left - 3, y: -27), .init(x: edge - 3, y: -36), .init(x: edge + 4, y: -11), .init(x: left, y: -2)], [0xFFF2D2, 0xE3D2A9, 0xC7C49E])
        for i in 0..<max(7, Int((edge - left) / 19)) {
            let x = left + CGFloat(i) * 19
            line([.init(x: x, y: -22), .init(x: x + 9, y: -6)], 0xB7B39A, 0.7, opacity: 0.6)
        }
        switch kind {
        case .clockTower:
            tower(at: CGPoint(x: -3, y: -20), size: 1.03, time: .init(hour: 10, minute: 25))
            cypress(at: CGPoint(x: right ? 36 : -36, y: -9), size: 0.82)
            lantern(at: CGPoint(x: -42, y: 2), size: 0.83)
        case .statue:
            cypress(at: CGPoint(x: right ? 39 : -39, y: -36), size: 1.13)
            dinoStatue(at: CGPoint(x: 0, y: -9), size: 0.94, mirror: right)
            fountain(at: CGPoint(x: 2, y: 17), size: 0.58)
            lantern(at: CGPoint(x: right ? -48 : 48, y: 8), size: 0.78)
        case .stairs:
            grandStaircase(at: CGPoint(x: 0, y: -3), size: 1, mirror: right)
        case .fountain:
            cypress(at: CGPoint(x: -40, y: -28), size: 0.88)
            cypress(at: CGPoint(x: 43, y: -30), size: 1.03)
            fountain(at: CGPoint(x: 0, y: -4), size: 1.14)
            for x: CGFloat in [-48, 48] { lantern(at: CGPoint(x: x, y: 8), size: 0.79) }
        case .palace:
            palace(at: CGPoint(x: 0, y: -15), size: 1)
            for x: CGFloat in [-63, 65] { lantern(at: CGPoint(x: x, y: 4), size: 0.85) }
        case .gate:
            gate(at: CGPoint(x: 0, y: -10), size: 0.95)
        }
        flowers(at: CGPoint(x: -width / 2 + 8, y: 13), size: variation % 2 == 0 ? 0.69 : 0.83)
        planter(at: CGPoint(x: width / 2 - 9, y: 17), size: 0.73)
        ivy(at: CGPoint(x: -width / 2 + 12, y: -20), size: 0.47)
    }

    private func grandStaircase(at point: CGPoint, size: CGFloat, mirror: Bool) {
        at(point, size: size, mirror: mirror) { p in
            // A tall flight narrows towards the upper landing. Side walls,
            // treads and individual balusters all share these vanishing lines.
            func edge(_ t: CGFloat, side: CGFloat) -> CGPoint {
                CGPoint(x: -17 + 24 * t + side * (21 + 32 * t), y: -148 + 157 * t)
            }
            for side: CGFloat in [-1, 1] {
                let top = edge(0, side: side), bottom = edge(1, side: side)
                p.polygon([.init(x: top.x + side * 8, y: top.y - 12), .init(x: bottom.x + side * 10, y: bottom.y - 15), .init(x: bottom.x + side * 10, y: bottom.y + 17), .init(x: top.x + side * 8, y: top.y + 34)], [0xF7E7C3, 0xC2BC9C, 0x9DA78E])
            }
            for i in 0..<15 {
                let t = CGFloat(i) / 15, next = CGFloat(i + 1) / 15
                let left = edge(t, side: -1), right = edge(t, side: 1)
                let a = edge(next, side: -1), b = edge(next, side: 1)
                p.polygon([left, right, .init(x: b.x, y: b.y - 4), .init(x: a.x, y: a.y - 4)], [0xFFEFCE, 0xDFD2B4, 0xCCC4A9])
                p.polygon([.init(x: a.x, y: a.y - 4), .init(x: b.x, y: b.y - 4), b, a], [0xB6B39F, 0xA2A893])
                p.line([.init(x: a.x, y: a.y - 4), .init(x: b.x, y: b.y - 4)], 0xFFF7DC, 1.5)
                if i % 3 == 0 { p.line([.init(x: (a.x + b.x) / 2, y: a.y - 8), .init(x: (a.x + b.x) / 2 + 1, y: a.y - 5)], 0xB6AD92, 0.7) }
            }
            for side: CGFloat in [-1, 1] {
                for i in 0...7 {
                    let t = CGFloat(i) / 7, e = edge(t, side: side)
                    p.rounded(CGRect(x: e.x + side * 5 - 2.5, y: e.y - 25, width: 5, height: 21), 2, [0xFFF1CE, 0xC6BE9D])
                    p.oval(CGRect(x: e.x + side * 5 - 4, y: e.y - 22, width: 8, height: 8), [0xF4E8C7, 0xBDB79B])
                }
                let a = edge(0, side: side), b = edge(1, side: side)
                p.line([.init(x: a.x + side * 5, y: a.y - 26), .init(x: b.x + side * 5, y: b.y - 26)], 0xAFAE94, 7)
                p.line([.init(x: a.x + side * 5, y: a.y - 28), .init(x: b.x + side * 5, y: b.y - 28)], 0xFFF1D1, 4)
                for t: CGFloat in [0, 0.53, 1] {
                    let e = edge(t, side: side)
                    p.masonry(CGRect(x: e.x + side * 5 - 6, y: e.y - 31, width: 12, height: 33))
                    p.rounded(CGRect(x: e.x + side * 5 - 8, y: e.y - 34, width: 16, height: 5), 1, [0xFFF5D8, 0xCCC09B])
                    if t == 0 || t == 1 { p.lantern(at: CGPoint(x: e.x + side * 5, y: e.y - 34), size: 0.52) }
                    else { p.banner(at: CGPoint(x: e.x + side * 5, y: e.y - 6), size: 0.42) }
                }
            }
            p.planter(at: CGPoint(x: -19, y: -147), size: 0.62)
            p.flowers(at: CGPoint(x: -48, y: 14), size: 0.59)
        }
    }

    private func lantern(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.rounded(CGRect(x: -7, y: -9, width: 14, height: 11), 2, [0xFFF0C0, 0xBCA16A])
            p.rounded(CGRect(x: -3, y: -27, width: 6, height: 21), 2, [0xFFE7A4, 0xAC8C54])
            p.glow(.init(x: 0, y: -42), radius: 23, color: 0xFFD679, opacity: 0.34)
            p.polygon([.init(x: -10, y: -55), .init(x: 10, y: -55), .init(x: 7, y: -29), .init(x: -7, y: -29)], [0xFFF8CD, 0xFFDC83, 0xE3AF52])
            p.polygon([.init(x: -13, y: -55), .init(x: 0, y: -68), .init(x: 13, y: -55)], [0xFFF0B6, 0xCCA45F, 0xAA864C])
            for x: CGFloat in [-9, 0, 9] { p.line([.init(x: x, y: -54), .init(x: x * 0.73, y: -29)], 0xB9914F, x == 0 ? 1.4 : 2.2) }
            p.line([.init(x: -8, y: -29), .init(x: 8, y: -29)], 0xBC9655, 3)
            p.line([.init(x: -4, y: -49), .init(x: -3, y: -36)], 0xFFFFED, 2)
            p.oval(CGRect(x: -2.5, y: -73, width: 5, height: 7), [0xFFF4C5, 0xCBA55C])
        }
    }

    private func dinoStatue(at point: CGPoint, size: CGFloat, mirror: Bool) {
        at(point, size: size, mirror: mirror) { p in
            p.masonry(CGRect(x: -32, y: -5, width: 64, height: 24))
            p.rounded(CGRect(x: -39, y: 17, width: 78, height: 7), 2, [0xFBEDCE, 0xC2BA98])
            p.oval(CGRect(x: -39, y: -14, width: 78, height: 21), [0xFFF3D1, 0xD1C4A0, 0xA9AE94])
            p.rounded(CGRect(x: -12, y: 1, width: 24, height: 13), 2, [0xCFB36E, 0xA68F59])
            p.crown(at: CGPoint(x: 0, y: 7), size: 0.37)
            var stone = Path()
            // Tail, belly, long neck and a friendly broad dino muzzle form one
            // carved silhouette; the near legs sit over its far-side limbs.
            stone.move(to: .init(x: -17, y: -24))
            stone.addCurve(to: .init(x: -59, y: -50), control1: .init(x: -39, y: -23), control2: .init(x: -63, y: -27))
            stone.addCurve(to: .init(x: -24, y: -45), control1: .init(x: -53, y: -42), control2: .init(x: -37, y: -43))
            stone.addCurve(to: .init(x: 2, y: -80), control1: .init(x: -47, y: -99), control2: .init(x: -8, y: -104))
            stone.addCurve(to: .init(x: 6, y: -127), control1: .init(x: 9, y: -91), control2: .init(x: -1, y: -112))
            stone.addCurve(to: .init(x: 30, y: -147), control1: .init(x: 9, y: -146), control2: .init(x: 17, y: -151))
            stone.addCurve(to: .init(x: 45, y: -133), control1: .init(x: 42, y: -147), control2: .init(x: 43, y: -141))
            stone.addCurve(to: .init(x: 51, y: -117), control1: .init(x: 62, y: -135), control2: .init(x: 61, y: -120))
            stone.addQuadCurve(to: .init(x: 29, y: -120), control: .init(x: 39, y: -112))
            stone.addCurve(to: .init(x: 22, y: -54), control1: .init(x: 19, y: -100), control2: .init(x: 37, y: -76))
            stone.addCurve(to: .init(x: 9, y: -21), control1: .init(x: 28, y: -35), control2: .init(x: 23, y: -24))
            stone.closeSubpath()
            p.rounded(CGRect(x: -18, y: -39, width: 14, height: 35), 6, [0xC7C6B4, 0xA4AE9E])
            p.rounded(CGRect(x: 11, y: -42, width: 13, height: 37), 5, [0xB8BCAA, 0x8E9C92])
            p.material(stone, [0xFFF0CF, 0xDDD5B9, 0xBABDA9, 0x8F9F95])
            p.oval(CGRect(x: -34, y: -75, width: 47, height: 46), [0xECE3C7, 0xC3C4AF, 0xA1AF9D])
            p.rounded(CGRect(x: -30, y: -43, width: 18, height: 39), 7, [0xEEE3C4, 0xC5C6AE, 0xA0AD9A])
            p.rounded(CGRect(x: 3, y: -46, width: 16, height: 42), 6, [0xF5E8C6, 0xC6C6AC, 0xA1AD98])
            // Fine staggered joints are clipped into the carved stone.
            var joints = p.context; joints.clip(to: stone)
            let seams = CastleWorldPainter(context: joints)
            for row in 0..<9 {
                let y = -139 + CGFloat(row) * 15
                seams.line([.init(x: -58, y: y), .init(x: 58, y: y + 2)], 0xA4AD9B, 0.75, opacity: 0.66)
                for col in 0..<5 {
                    let x = -46 + CGFloat(col) * 23 + CGFloat(row % 2) * 11
                    seams.line([.init(x: x, y: y + 1), .init(x: x - 2, y: y + 15)], 0xA4AD9B, 0.65, opacity: 0.63)
                }
                seams.line([.init(x: -58, y: y + 2), .init(x: 58, y: y + 4)], 0xFFF5D9, 0.6, opacity: 0.65)
            }
            p.oval(CGRect(x: 29, y: -139, width: 6, height: 8), [0x667E78, 0x364F50])
            p.oval(CGRect(x: 30, y: -138, width: 1.8, height: 2.2), [0xFFF3D4, 0xD4D7C0])
            p.oval(CGRect(x: 49, y: -128, width: 3, height: 3), [0x9BA797, 0x6F8980])
            var smile = Path(); smile.move(to: .init(x: 31, y: -125))
            smile.addQuadCurve(to: .init(x: 52, y: -122), control: .init(x: 40, y: -118))
            p.context.stroke(smile, with: .color(Color(dinoHex: 0x8D9D8D)), style: StrokeStyle(lineWidth: 1.2, lineCap: .round))
            for x: CGFloat in [-27, -21, 7, 12] { p.line([.init(x: x, y: -9), .init(x: x, y: -5)], 0x8C9F8F, 0.8) }
            p.crown(at: CGPoint(x: 24, y: -149), size: 1.06)
            p.polygon([.init(x: 24, y: -153), .init(x: 27, y: -149), .init(x: 24, y: -145), .init(x: 21, y: -149)], [0xB8E2E6, 0x347CA5])
            p.ivy(at: CGPoint(x: -29, y: 1), size: 0.26)
        }
    }

    private func palace(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            // Rear keep and thin spires give the castle several distinct depths.
            p.tower(at: CGPoint(x: 31, y: -54), size: 0.75, time: nil)
            p.masonry(CGRect(x: -47, y: -146, width: 94, height: 143))
            p.roof(at: CGPoint(x: 0, y: -150), size: 1.18)
            p.rounded(CGRect(x: -51, y: -85, width: 102, height: 7), 2, [0xFFF5D6, 0xCCBA93])
            for x: CGFloat in [-27, 0, 27] {
                p.rounded(CGRect(x: x - 7, y: -129, width: 14, height: 29), 7, [0xD8C7A3, 0xB2AA8D])
                p.rounded(CGRect(x: x - 4.5, y: -126, width: 9, height: 25), 4.5, [0xA7CCD2, 0x456D8F])
                p.line([.init(x: x, y: -124), .init(x: x, y: -103)], 0xEFD69F, 1)
            }
            p.rounded(CGRect(x: -20, y: -67, width: 40, height: 63), 19, [0xC1B28D, 0x8A9D95])
            p.rounded(CGRect(x: -15, y: -62, width: 30, height: 58), 14, [0x729EB7, 0x254C7D])
            p.line([.init(x: 0, y: -57), .init(x: 0, y: -7)], 0xE3C17F, 1.4)
            p.crown(at: CGPoint(x: 0, y: -34), size: 0.61)
            for (x, s): (CGFloat, CGFloat) in [(-59, 0.83), (59, 0.95)] {
                p.tower(at: CGPoint(x: x, y: -4), size: s, time: nil)
            }
            for i in 0..<4 {
                p.rounded(CGRect(x: -27 - CGFloat(i) * 4, y: -3 + CGFloat(i) * 6, width: 54 + CGFloat(i) * 8, height: 6), 1, [0xFFF0CC, 0xB9B79A])
            }
            p.ivy(at: CGPoint(x: -43, y: -83), size: 0.76)
            p.planter(at: CGPoint(x: 43, y: 11), size: 0.7)
        }
    }

    private func masonry(_ rect: CGRect) {
        rounded(rect, 7, [0xFFF1D0, 0xE2D0AC, 0xB6B49D])
        var blocks = context; blocks.clip(to: Path(roundedRect: rect, cornerRadius: 7))
        let texture = CastleWorldPainter(context: blocks)
        for row in 0...Int(rect.height / 18) {
            let y = rect.minY + CGFloat(row) * 18
            let cellWidth = max(14, min(31, rect.width / 3))
            for col in -1...Int(rect.width / cellWidth) {
                let x = rect.minX + CGFloat(col) * cellWidth + (row % 2 == 0 ? 0 : cellWidth / 2)
                let light = (row * 17 + col * 11 + 73) % 5
                let block = CGRect(x: x + 1, y: y + 1, width: cellWidth - 2, height: 16)
                if light == 0 {
                    blocks.fill(Path(roundedRect: block, cornerRadius: 2), with: .color(Color(dinoHex: 0xFFF9DE).opacity(0.3)))
                } else if light == 2 {
                    blocks.fill(Path(roundedRect: block, cornerRadius: 2), with: .color(Color(dinoHex: 0x9DA790).opacity(0.14)))
                }
                texture.line([.init(x: block.minX + 2, y: block.minY), .init(x: block.maxX - 3, y: block.minY)], 0xFFFAE1, 0.65, opacity: 0.55)
                if light == 3 && rect.width > 25 {
                    texture.line([.init(x: x + 9, y: y + 6), .init(x: x + 12, y: y + 8), .init(x: x + 11, y: y + 12)], 0x9FA68D, 0.5, opacity: 0.5)
                }
            }
        }
        let rows = Int(rect.height / 18)
        for i in 1...max(1, rows) {
            let y = rect.minY + CGFloat(i) * 18
            line([.init(x: rect.minX + 3, y: y), .init(x: rect.maxX - 3, y: y)], 0xB5B39D, 0.8, opacity: 0.62)
            for j in 0..<3 {
                let x = rect.minX + CGFloat(j) * rect.width / 3 + (i % 2 == 0 ? 0 : rect.width / 6)
                if x > rect.minX + 2 { line([.init(x: x, y: y - 17), .init(x: x, y: y - 1)], 0xB4B39D, 0.7, opacity: 0.6) }
            }
            line([.init(x: rect.minX + 4, y: y + 1), .init(x: rect.maxX - 4, y: y + 1)], 0xFFF6D8, 0.7, opacity: 0.55)
        }
    }
    private func terrace(width: CGFloat) {
        masonry(CGRect(x: -width / 2, y: -4, width: width, height: 29))
        oval(CGRect(x: -width / 2, y: -13, width: width, height: 29), [0xFFF0C8, 0xDED2AA, 0xB9B79C])
        context.stroke(Path(ellipseIn: CGRect(x: -width / 2 + 3, y: -10, width: width - 6, height: 23)), with: .color(Color(dinoHex: 0xFFFFE4).opacity(0.76)), lineWidth: 1.2)
    }
    private func roof(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            let roof = Path { r in
                r.move(to: .init(x: -38, y: 0)); r.addLine(to: .init(x: -1, y: -57))
                r.addLine(to: .init(x: 7, y: -55)); r.addLine(to: .init(x: 39, y: 0)); r.closeSubpath()
            }
            p.material(roof, [0x94B9DE, 0x346FB2, 0x203F7F])
            p.polygon([.init(x: -1, y: -57), .init(x: 8, y: -55), .init(x: 39, y: 0), .init(x: 7, y: -1)], [0x4B78B0, 0x233F78])
            var tiles = p.context; tiles.clip(to: roof)
            let local = CastleWorldPainter(context: tiles)
            for row in 0..<7 {
                let y = CGFloat(row) * 8 - 49
                for col in 0..<10 {
                    let x = CGFloat(col) * 10 - 48 + CGFloat(row % 2) * 5
                    var tile = Path(); tile.move(to: .init(x: x, y: y))
                    tile.addQuadCurve(to: .init(x: x + 10, y: y), control: .init(x: x + 5, y: y + 6))
                    tiles.stroke(tile, with: .color(Color(dinoHex: 0xC2D5E1).opacity(0.55)), lineWidth: 0.65)
                    local.line([.init(x: x + 5, y: y + 3), .init(x: x + 5, y: y + 7)], 0x325383, 0.5, opacity: 0.4)
                }
            }
            p.rounded(CGRect(x: -40, y: -1, width: 82, height: 7), 3, [0xFFE9A8, 0xCEA96B, 0xA09268])
            for x: CGFloat in [-29, -10, 10, 29] { p.oval(CGRect(x: x - 1.5, y: 1, width: 3, height: 3), [0xFFF5C4, 0xBA955A]) }
            p.oval(CGRect(x: -4, y: -64, width: 12, height: 12), [0xFFF0AE, 0xD7B470, 0xB09560])
            p.line([.init(x: 2, y: -63), .init(x: 2, y: -87)], 0xD4B16C, 1.6)
            p.polygon([.init(x: 3, y: -87), .init(x: 28, y: -81), .init(x: 18, y: -72), .init(x: 3, y: -76)], [0x6FA6D4, 0x285D9E])
            p.line([.init(x: 5, y: -85), .init(x: 23, y: -81), .init(x: 17, y: -75)], 0xFFE6A4, 0.9)
        }
    }
    private func crown(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.polygon([.init(x: -11, y: -7), .init(x: -4, y: -3), .init(x: 0, y: -13), .init(x: 4, y: -3), .init(x: 11, y: -7), .init(x: 8, y: 6), .init(x: -8, y: 6)], [0xFFF0AE, 0xDAB66C])
            p.line([.init(x: -7, y: 3), .init(x: 7, y: 3)], 0xFFF6C7, 1)
            for x: CGFloat in [-10, 0, 10] { p.oval(CGRect(x: x - 1.3, y: (x == 0 ? -14 : -8), width: 2.6, height: 2.6), [0xFFFFCD, 0xDFBF79]) }
        }
    }
    private func banner(at point: CGPoint, size: CGFloat) {
        at(point, size: size) { p in
            p.polygon([.init(x: -15, y: -40), .init(x: 15, y: -40), .init(x: 15, y: 9), .init(x: 0, y: 23), .init(x: -15, y: 9)], [0x659ACC, 0x2F65AC, 0x244A88])
            p.polygon([.init(x: -10, y: -38), .init(x: -4, y: -38), .init(x: -5, y: 12), .init(x: -10, y: 7)], [0x92B6DD, 0x386CAD])
            p.line([.init(x: -13, y: -38), .init(x: -13, y: 7), .init(x: 0, y: 20), .init(x: 13, y: 7), .init(x: 13, y: -38)], 0xE9C984, 1)
            p.line([.init(x: -19, y: -42), .init(x: 19, y: -42)], 0xD8B371, 3)
            p.crown(at: CGPoint(x: 0, y: -14), size: 0.68)
